const ARCH_ADJ = {
  "Rigid & Principled":["Unbending","Iron","Sworn"], "Pragmatic & Flexible":["Expedient","Calculating","Adaptive"],
  "Loyalty-Bound":["Faithful","Bound","Devoted"], "Self-Interested":["Self-Serving","Hungry","Unmoored"],
  "Secure":["Steady","Grounded"], "Anxious":["Restless","Clinging"], "Avoidant":["Distant","Walled"], "Disorganized":["Fractured","Storm-Tossed"],
  "Dry & Deadpan":["Dry","Deadpan","Unimpressed"], "Self-Deprecating":["Self-Mocking","Rueful","Apologetic"],
  "Cruel & Barbed":["Barbed","Cutting","Merciless"], "Warm & Playful":["Warm","Sunlit","Easy"],
  "Absurd & Chaotic":["Unhinged","Riotous","Unpredictable"], "Humorless & Absent":["Mirthless","Grave","Unsmiling"],
  "Substance & Consumption":["Sodden","Steeped","Unsteady"], "Compulsion & Ritual":["Ritual-Bound","Counting","Exacting"],
  "Risk & Escape":["Reckless","Chance-Taking","Unmoored"], "Restraint & Discipline":["Ascetic","Measured","Held"],
  // Stress categories were listed as an adjective source in emergentArchetypeName's
  // adjSrc, but had no ARCH_ADJ entries at all — so stress could never actually
  // contribute an adjective and silently dropped out of every composed name.
  "Fight (attack the threat)":["Cornered","Bristling","Unyielding"],
  "Flight (remove yourself)":["Fleeing","Half-Gone","Untethered"],
  "Freeze (shut down)":["Frozen","Stalled","Silent"],
  "Fawn (appease the threat)":["Yielding","Placating","Bending"],
  "Idealistic & Visionary":["Visionary","Idealist","Hopeful"], "Intellectual & Wordplay":["Clever","Sharp-Tongued","Witty"],
  "Avoidance & Procrastination":["Evasive","Elusive","Delaying"],
};
const ARCH_NOUN = {
  "Leader":["Commander","Captain","Head"], "Peacemaker":["Mediator","Binder","Peacekeeper"],
  "Instigator":["Provocateur","Spark","Agitator"], "Outsider":["Outsider","Stranger","Wanderer"],
  "Caretaker":["Guardian","Keeper","Tender"], "Skeptic":["Skeptic","Doubter","Auditor"],
  "Fight (attack the threat)":["Fighter"], "Flight (remove yourself)":["Runner"],
  "Freeze (shut down)":["Stillness"], "Fawn (appease the threat)":["Appeaser"],
  "Connector":["Connector","Bridge","Networker"],
};
// Deterministic when a seed is given (mulberry32 PRNG off a string hash), otherwise
// falls back to Math.random(). Lets any caller opt into repeatable output — e.g. the
// same character name always composing the same emergent title — without a global mode.
function seededRandom(seed){
  let h = 0;
  for (let i=0;i<seed.length;i++){ h = Math.imul(31, h) + seed.charCodeAt(i) | 0; }
  return function(){
    h |= 0; h = h + 0x6D2B79F5 | 0;
    let t = Math.imul(h ^ h >>> 15, 1 | h);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
function pickFrom(arr, seed){
  const rand = seed ? seededRandom(String(seed)) : Math.random;
  return arr[Math.floor(rand()*arr.length)];
}
function emergentArchetypeName(st){
  const catOf = id => (st["prof_"+id+"_0"] ? st["prof_"+id+"_0"].trait.category : null);
  const values = catOf("values"), role = catOf("role"), stress = catOf("stress");
  const attach = catOf("attachment"), humor = catOf("humor"), vices = catOf("vices");
  if (values && role && ARCH_NAMES[values+"|"+role]) return {name:ARCH_NAMES[values+"|"+role], exact:true};
  if (stress && role && ARCH_NAMES[stress+"|"+role]) return {name:ARCH_NAMES[stress+"|"+role], exact:true};
  if (attach && role && ARCH_NAMES[attach+"|"+role]) return {name:ARCH_NAMES[attach+"|"+role], exact:true};
  // compose — seeded off the actual chosen categories, so the same profile always
  // composes the same name instead of re-rolling a different one on every render.
  const seed = [values, role, stress, attach, humor, vices].filter(Boolean).join("|");
  const adjSrc = [values, attach, humor, vices, stress].filter(c=>c && ARCH_ADJ[c]);
  const nounSrc = [role, stress].filter(c=>c && ARCH_NOUN[c]);
  if (adjSrc.length && nounSrc.length){
    return {name:"The " + pickFrom(ARCH_ADJ[pickFrom(adjSrc, seed+"a")], seed+"a2") + " " + pickFrom(ARCH_NOUN[pickFrom(nounSrc, seed+"n")], seed+"n2"), exact:false};
  }
  if (nounSrc.length) return {name:"The " + pickFrom(ARCH_NOUN[pickFrom(nounSrc, seed+"n")], seed+"n2"), exact:false};
  return null;
}

// ================= SOFT TENSION FLAGS (non-blocking) =================
// Distinct from hard conflicts: these combinations are coherent but uncommon.
const TENSION_RULES = [
  {a:{sec:"attachment",cat:"Secure"}, b:{sec:"motivation",fragment:"Betrayed by kin|Abandoned young|Broken promise|Physically harmed"},
   note:"Secure attachment alongside a betrayal/abandonment wound is possible — it usually means real repair happened. Worth knowing what did it."},
  {a:{sec:"values",cat:"Rigid & Principled"}, b:{sec:"humor",cat:"Cruel & Barbed"},
   note:"Strict principles with cruel humour: the cruelty is likely aimed only at those they judge to have failed the standard."},
  {a:{sec:"role",cat:"Leader"}, b:{sec:"stress",cat:"Freeze (shut down)"},
   note:"A leader who freezes under pressure is dramatically rich, but the group will notice. Consider when they've been caught out."},
  {a:{sec:"values",cat:"Self-Interested"}, b:{sec:"role",cat:"Caretaker"},
   note:"Self-interest in a caretaking seat — the care is real but transactional. Ask what they're collecting."},
  {a:{sec:"vices",cat:"Restraint & Discipline"}, b:{sec:"stress",cat:"Flight (remove yourself)"},
   note:"Rigorous self-discipline paired with a flight response: the routine is likely the thing they flee into."},
  {a:{sec:"attachment",cat:"Avoidant"}, b:{sec:"role",cat:"Caretaker"},
   note:"Avoidant attachment in a caretaker: they tend to everyone's needs precisely so nobody asks about theirs."},
  {a:{sec:"humor",cat:"Warm & Playful"}, b:{sec:"motivation",fragment:"Fear of intimacy|unlovable|Nobody stays"},
   note:"Warm humour over an intimacy fear — the charm is usually the defence. Very playable."},
  {a:{sec:"values",cat:"Loyalty-Bound"}, b:{sec:"attachment",cat:"Disorganized"},
   note:"Absolute loyalty with disorganized attachment: they will not leave, and will not be at peace staying."},
];
function softTensionsFor(st){
  const out = [];
  const catOf = id => (st["prof_"+id+"_0"] ? st["prof_"+id+"_0"].trait.category : null);
  const motivText = Object.keys(st).filter(k=>k.startsWith("prof_motivation_"))
                    .map(k=>st[k].trait.trait+" "+st[k].trait.desc).join(" | ");
  const match = (spec) => {
    if (spec.sec === "motivation") return spec.fragment ? new RegExp(spec.fragment,"i").test(motivText) : false;
    return catOf(spec.sec) === spec.cat;
  };
  TENSION_RULES.forEach(r=>{ if (match(r.a) && match(r.b)) out.push(r.note); });
  return out;
}

// ================= COHERENCE SCORE =================
// Measures how many of the chosen categories were actually reinforced by the
// weight matrix versus arrived at independently. Not a quality judgement.
/* ================= SECOND-ORDER TENSIONS =================
   The pairwise detector catches "trait A pulls +honesty, trait B pulls -honesty."
   These rules catch PATTERNS: specific three-part configurations of resolved
   categories and axis posture that add up to a recognizable kind of person —
   often the most interesting thing on the sheet, so they get named. Each rule:
   {need: predicates over categories present + axis sums, name, note}. */
function _catsPresent(st){
  const cats = new Set();
  Object.values(st).forEach(s=>{ if (s && s.trait) cats.add(s.trait.category); });
  return cats;
}
const SECOND_ORDER_RULES = [
  {name:"The honest appeaser",
   test:(c,ax)=> c.has("Fawn (appease the threat)") && (ax.hon||0) >= 2,
   note:"Deep truthfulness plus a fawn stress response: they cannot lie and cannot confront, so under pressure they tell the truth apologetically, softening facts they refuse to change. Scenes with them read as confession delivered as customer service."},
  {name:"The armoured caretaker",
   test:(c,ax)=> c.has("Caretaker") && (ax.emo||0) <= -2,
   note:"Devoted caretaking with a sealed interior: all love is expressed logistically — food, repairs, cover — and direct emotional bids make them visibly uncomfortable. The care is real; the words for it are missing."},
  {name:"The principled deceiver",
   test:(c,ax)=> c.has("Rigid & Principled") && (ax.hon||0) <= -2,
   note:"An unbendable private code inside a habitually dishonest exterior. They lie freely about small things and are absolutely immovable on the few things that count — and outsiders can't tell which register they're in."},
  {name:"The lonely connector",
   test:(c,ax)=> c.has("Connector") && (ax.warm||0) <= -1,
   note:"Runs everyone's relationships while staying personally unreachable. The web of introductions and favours is real infrastructure — and it's also the wall."},
  {name:"The volatile perfectionist",
   test:(c,ax)=> (c.has("Compulsion & Ritual") || c.has("Upkeep — Immaculate")) && (ax.mood||0) <= -2,
   note:"Ritual and immaculate order maintained on top of visible emotional volatility: the discipline isn't a personality, it's a container. Watch what happens to the routine on the bad days — that's the barometer everyone learns to read."},
  {name:"The doubting idealist",
   test:(c,ax)=> c.has("Idealistic & Visionary") && (ax.pos||0) <= -1,
   note:"Committed to a vision they no longer fully believe will arrive. They keep building anyway, which reads either as heroism or as inability to stop, depending on the day and the observer."},
  {name:"The frozen leader",
   test:(c,ax)=> c.has("Leader") && c.has("Freeze (shut down)"),
   note:"Carries command in ordinary time and locks up in crisis — the exact moment the role exists for. Either the group has quietly built around this, or the first real emergency will be the story."},
  {name:"The self-erasing instigator",
   test:(c,ax)=> c.has("Instigator") && (ax.ego||0) <= -2,
   note:"Destabilizes every room while holding themselves in contempt. The provocations aren't confidence; they're a way of mattering to a group they don't believe would keep them otherwise."},
  {name:"The secure cynic",
   test:(c,ax)=> c.has("Secure") && (ax.pos||0) <= -2,
   note:"Expects the worst of the world and none of it from their people. Total pessimism about plans, institutions, and weather; total, unshakeable faith in about four specific humans."},
  {name:"The disciplined escapist",
   test:(c,ax)=> c.has("Risk & Escape") && (ax.disc||0) >= 2,
   note:"Meticulous, controlled, reliable — and periodically, deliberately, courts real danger. The recklessness is scheduled. That's the unsettling part."},
];
function secondOrderTensions(st){
  const cats = _catsPresent(st);
  const ax = axisProfile(st);
  return SECOND_ORDER_RULES.filter(r=>{ try{ return r.test(cats, ax); }catch(e){ return false; } })
    .map(r=>({name:r.name, note:r.note}));
}

function coherenceScore(st){
  const chosen = {};
  PROFILE_SECTIONS.forEach(ps=>{ const s = st["prof_"+ps.id+"_0"]; if (s) chosen[ps.id] = s.trait.category; });
  let reinforced = 0, total = 0;
  const kinds = {vocab:VOCAB_CATS, grammar:GRAMMAR_CATS, manner:MANNER_CATS};
  Object.entries(kinds).forEach(([kind, cats])=>{
    const fragMap = accumulateBoost(kind, chosen);
    const boostMap = resolveBoostMapForCats(cats, fragMap);
    const picked = Object.keys(st).filter(k=>{
      if (kind==='vocab') return k.startsWith('vocab');
      if (kind==='grammar') return k==='grammar';
      return k.startsWith('manner');
    }).map(k=>st[k].trait.category);
    picked.forEach(c=>{ total++; if ((boostMap.get(c)||0) > 0) reinforced++; });
  });
  PROFILE_SECTIONS.forEach(ps=>{
    if (ps.drawAll || !chosen[ps.id]) return;
    const fragMap = accumulateBoost(ps.id, {});
    const boostMap = resolveBoostMapForCats(catsOf(ps.section), fragMap);
    total++; if ((boostMap.get(chosen[ps.id])||0) > 0) reinforced++;
  });
  if (!total) return null;
  const pct = Math.round(100 * reinforced / total);

  // ---- Chance baseline ----------------------------------------------------
  // Raw coherence alone is misleading: depth-first resolves profile categories
  // FIRST, which then boost large swathes of the voice categories, so a bigger
  // share of the pool counts as "reinforced" before any pick is even made. The
  // score therefore rises for structural reasons rather than because the
  // character hangs together better. So we also compute what a purely random
  // character would score given the exact same boost maps, and report the lift
  // over that. Lift is what actually tells you something.
  let baseHits = 0, baseTotal = 0;
  Object.entries(kinds).forEach(([kind, cats])=>{
    const boostMap = resolveBoostMapForCats(cats, accumulateBoost(kind, chosen));
    const boostedCount = cats.filter(c=>(boostMap.get(c)||0) > 0).length;
    const picksOfKind = Object.keys(st).filter(k=>{
      if (kind==='vocab') return k.startsWith('vocab');
      if (kind==='grammar') return k==='grammar';
      return k.startsWith('manner');
    }).length;
    // expected share of random picks that would land on a boosted category
    baseHits += picksOfKind * (cats.length ? boostedCount/cats.length : 0);
    baseTotal += picksOfKind;
  });
  PROFILE_SECTIONS.forEach(ps=>{
    if (ps.drawAll || !chosen[ps.id]) return;
    const cats = catsOf(ps.section);
    const boostMap = resolveBoostMapForCats(cats, accumulateBoost(ps.id, {}));
    const boostedCount = cats.filter(c=>(boostMap.get(c)||0) > 0).length;
    baseHits += cats.length ? boostedCount/cats.length : 0;
    baseTotal += 1;
  });
  const basePct = baseTotal ? Math.round(100 * baseHits / baseTotal) : 0;
  const lift = pct - basePct;

  // Label is now driven by LIFT, not raw percentage, so it means the same thing
  // whichever generation mode produced the character.
  let label;
  if (lift >= 25) label = "Tightly coherent — picks reinforce each other well beyond chance.";
  else if (lift >= 10) label = "Moderately coherent — a real pull toward consistency.";
  else if (lift >= -5) label = "About as connected as a random draw — fine for surprise, harder to justify.";
  else label = "Deliberately scattered — picks actively avoid the expected pairings.";
  return {pct, basePct, lift, label, reinforced, total};
}

// ================= DEPTH-FIRST STAGED GENERATION =================
// Reverses the causal order: resolve the deep facts (wound, attachment, values,
// stress) FIRST, derive personality slider positions FROM them, then build voice.
const DEPTH_TO_PERSONALITY = {
  "Secure":{confidence:45, emotionalcapacity:35}, "Anxious":{confidence:-55, emotionalcapacity:45},
  "Avoidant":{emotionalcapacity:-65, friendliness:-40}, "Disorganized":{discipline:-35, emotionalcapacity:20},
  "Rigid & Principled":{discipline:55, honesty:60, rebelliousness:-20}, "Pragmatic & Flexible":{honesty:-35, intelligence:40},
  "Loyalty-Bound":{friendliness:40, agreeableness:35}, "Self-Interested":{friendliness:-45, honesty:-50},
  "Fight (attack the threat)":{assertiveness:60, agreeableness:-45}, "Flight (remove yourself)":{assertiveness:-40},
  "Freeze (shut down)":{confidence:-50}, "Fawn (appease the threat)":{agreeableness:60, assertiveness:-55},
  "Leader":{assertiveness:50, confidence:45}, "Peacemaker":{agreeableness:50, friendliness:40},
  "Instigator":{rebelliousness:55, agreeableness:-35}, "Outsider":{friendliness:-50, rebelliousness:30},
  "Caretaker":{friendliness:50, emotionalcapacity:40}, "Skeptic":{intelligence:50, positivity:-35, curiosity:35},
  "Dry & Deadpan":{intelligence:35, emotionalcapacity:-30}, "Self-Deprecating":{confidence:-45},
  "Cruel & Barbed":{friendliness:-45, agreeableness:-35}, "Warm & Playful":{friendliness:50, positivity:45},
  "Absurd & Chaotic":{discipline:-45, rebelliousness:35}, "Humorless & Absent":{positivity:-40, discipline:30},
  "Substance & Consumption":{discipline:-50}, "Compulsion & Ritual":{discipline:35, confidence:-30},
  "Risk & Escape":{discipline:-45, rebelliousness:40}, "Restraint & Discipline":{discipline:65},
  "Connector":{friendliness:40, activeness:30}, "Idealistic & Visionary":{honesty:35, positivity:45, curiosity:30},
  "Intellectual & Wordplay":{intelligence:40, curiosity:40}, "Avoidance & Procrastination":{discipline:-45, confidence:-25, curiosity:-20},
};
function deriveDepthCategories(){
  // Resolve profile types with NO personality influence — pure roll / manual choice.
  const chosen = {};
  PROFILE_SECTIONS.forEach(ps=>{
    if (ps.drawAll) return;
    const tog = document.getElementById('sec_'+ps.id);
    if (tog && !tog.checked) return;
    const sel = document.getElementById('type_'+ps.id);
    if (sel && sel.value) { chosen[ps.id] = sel.value; return; }
    const cats = catsOf(ps.section);
    // biased only by already-chosen deep facts, never by sliders
    const boostMap = resolveBoostMapForCats(cats, accumulateBoost(ps.id, chosen, ZERO_PERSONALITY()));
    chosen[ps.id] = pickCategoryWeighted(cats, boostMap);
  });
  return chosen;
}
function ZERO_PERSONALITY(){
  const o={};
  PERSONALITY_AXES.forEach(a=>o[a.id]=0);
  // Depth-first resolution is meant to be untouched by ANY current slider, voice
  // included — without this, verbosity/register/composure would still leak in via
  // axisLevel's live-DOM fallback now that they're wired into the same signal system.
  VOICE_AXES.forEach(a=>o[a.id]=0);
  return o;
}
function personalityFromDepth(chosen){
  const acc = {}; const counts = {};
  Object.values(chosen).forEach(cat=>{
    const map = DEPTH_TO_PERSONALITY[cat];
    if (!map) return;
    Object.entries(map).forEach(([axis,val])=>{
      acc[axis] = (acc[axis]||0) + val; counts[axis] = (counts[axis]||0)+1;
    });
  });
  const out = {};
  PERSONALITY_AXES.forEach(a=>{
    if (counts[a.id]){
      out[a.id] = Math.round(clamp(acc[a.id]/counts[a.id], -100, 100));
    } else {
      // No profile category implies this axis. Previously this returned 0, which
      // silently WIPED whatever the user had deliberately set on axes the depth
      // map doesn't cover (Manners, Activeness, Curiosity). Preserve their value
      // instead — depth-first should derive what it can and leave the rest alone.
      const el = document.getElementById('pers_'+a.id);
      out[a.id] = el ? parseInt(el.value) : 0;
      out['__untouched_'+a.id] = true;
    }
  });
  return out;
}
function applyDepthFirst(){
  const chosen = deriveDepthCategories();
  const derived = personalityFromDepth(chosen);
  lastDepthUntouched = PERSONALITY_AXES.filter(a=>derived['__untouched_'+a.id]).map(a=>a.label);
  PERSONALITY_AXES.forEach(a=>{
    const el = document.getElementById('pers_'+a.id);
    if (el) el.value = derived[a.id];
  });
  // lock the resolved types into the dropdowns so the main build honours them
  Object.entries(chosen).forEach(([id,cat])=>{
    const sel = document.getElementById('type_'+id);
    if (sel && [...sel.options].some(o=>o.value===cat)) sel.value = cat;
  });
  onSliderChange();
  suggestVoiceFromPersonality();
  return chosen;
}

// ================= SEED FROM ONE TRAIT =================
let SEEDABLE_TRAITS = [];
function buildSeedPicker(){
  const sel = document.getElementById('seedTraitSelect');
  if (!sel) return;
  SEEDABLE_TRAITS = TRAITS.filter(t => t.section==="Personality Traits" ||
    PROFILE_SECTIONS.some(ps=>ps.section===t.section));
  renderSeedOptions(SEEDABLE_TRAITS);
}
function renderSeedOptions(list){
  const sel = document.getElementById('seedTraitSelect');
  const prevValue = sel.value;
  const bySection = {};
  list.forEach(t=>{ (bySection[t.section] = bySection[t.section]||[]).push(t); });
  sel.innerHTML = `<option value="">— none —</option>`;
  Object.entries(bySection).forEach(([sec, items])=>{
    const g = document.createElement('optgroup'); g.label = sec;
    items.sort((a,b)=>a.trait.localeCompare(b.trait)).forEach(t=>{
      const o = document.createElement('option'); o.value = String(t.id);
      o.textContent = `${t.trait} — ${t.category}`;
      g.appendChild(o);
    });
    sel.appendChild(g);
  });
  if ([...sel.options].some(o=>o.value===prevValue)) sel.value = prevValue;
}
function filterSeedPicker(){
  const q = document.getElementById('seedTraitFilter').value.trim().toLowerCase();
  if (!q){ renderSeedOptions(SEEDABLE_TRAITS); return; }
  const filtered = SEEDABLE_TRAITS.filter(t =>
    t.trait.toLowerCase().includes(q) || t.desc.toLowerCase().includes(q) || t.category.toLowerCase().includes(q));
  renderSeedOptions(filtered.length ? filtered : SEEDABLE_TRAITS);
}
function generateFromSeed(){
  const sel = document.getElementById('seedTraitSelect');
  const id = sel && sel.value ? parseInt(sel.value) : null;
  if (!id){ alert("Choose a seed trait first."); return; }
  const seed = TRAITS.find(t=>t.id===id);
  if (!seed) return;

  // 1. If the seed is a profile-section trait, lock that section's type to its category.
  const ps = PROFILE_SECTIONS.find(p=>p.section===seed.section);
  if (ps){
    const tsel = document.getElementById('type_'+ps.id);
    if (tsel && [...tsel.options].some(o=>o.value===seed.category)) tsel.value = seed.category;
    const tog = document.getElementById('sec_'+ps.id); if (tog) tog.checked = true;
  }
  // 2. If it's a personality trait, push that axis hard toward the seed's pole.
  if (seed.section === "Personality Traits"){
    const axis = PERSONALITY_AXES.find(a=>a.pos===seed.category || a.neg===seed.category || a.mid===seed.category);
    if (axis){
      const el = document.getElementById('pers_'+axis.id);
      // Seeding from a Situational trait means the character is deliberately
      // MIDDLE on that axis — park the slider inside the neutral band rather
      // than shoving it to a pole it doesn't belong to.
      if (el) el.value = (seed.category === axis.mid) ? 0
                       : (seed.category === axis.pos ? 75 : -75);
    }
  }
  // 3. Let the matrix propagate outward from that fixed point.
  const chosenSoFar = {};
  if (ps) chosenSoFar[ps.id] = seed.category;
  const derived = personalityFromDepth(chosenSoFar);
  PERSONALITY_AXES.forEach(a=>{
    const el = document.getElementById('pers_'+a.id);
    if (!el) return;
    if (seed.section === "Personality Traits"){
      const axis = PERSONALITY_AXES.find(x=>x.pos===seed.category || x.neg===seed.category);
      if (axis && axis.id === a.id) return; // don't overwrite the seeded axis
    }
    if (derived[a.id]) el.value = derived[a.id];
  });
  onSliderChange();
  suggestVoiceFromPersonality();
  generateCharacter();

  // 4. Force the exact seed trait into its slot and lock it.
  if (ps){
    const slotId = "prof_"+ps.id+"_0";
    if (state[slotId]){ state[slotId].trait = seed; state[slotId].locked = true; }
  } else if (seed.section === "Personality Traits"){
    const axis = PERSONALITY_AXES.find(a=>a.pos===seed.category || a.neg===seed.category);
    if (axis && state["pers_"+axis.id]){ state["pers_"+axis.id].trait = seed; state["pers_"+axis.id].locked = true; }
  }
  renderSheet(); checkConflicts();
}

// ================= SINGLE CHARACTER STATE =================
let state = {};
let pressureState = null;
let charMeta = {name:"", age:"", context:"", archetypeLabel:"Custom random"};
let history = [];
// The sliders that actually produced the CURRENTLY-DISPLAYED state. snapshotHistory
// runs at the top of generateCharacter(), which is AFTER the user has already moved
// the sliders to whatever they want for the NEXT generation — so capturing DOM values
// there would save the new sliders under the old undo entry. Track them separately,
// updated only once a generation actually completes.
let lastGeneratedSliders = null;
let charMetaSeed = null;
let diffLog = {}; // slotId -> {from, to}
let whyOpen = {};          // slotId -> bool, is the "why?" panel expanded
let rerollExclusions = {}; // slotId -> Set of trait ids already rejected here
let pinnedTargets = {};    // slotId -> pinned continuous intensity target (1..5), survives regeneration
let lastDepthUntouched = []; // axis labels depth-first left alone, for the notice
let lastAxesUsed = null;      // Set of axis ids included in the last generation
let lastAxisTrimActive = false; // was the "N (random)" personality-count trim in effect

// BUG FIX: snapshots captured only the trait state, so Undo restored old traits while
// leaving the sliders (and the Under Pressure sheet) wherever the last generation had
// moved them — the sheet and the controls disagreed, and the pressure panel showed a
// character that no longer existed. Capture all three.
function captureSliders(){
  const s = {};
  ['verbositySlider','registerSlider','composureSlider'].forEach(id=>{
    const el = document.getElementById(id); if (el) s[id] = el.value;
  });
  PERSONALITY_AXES.forEach(a=>{
    const el = document.getElementById('pers_'+a.id); if (el) s['pers_'+a.id] = el.value;
  });
  return s;
}
function restoreSliders(s){
  if (!s) return;
  Object.entries(s).forEach(([id,v])=>{ const el = document.getElementById(id); if (el) el.value = v; });
}
function snapshotHistory(){
  history.push({
    state: JSON.parse(JSON.stringify(state)),
    charMeta: {...charMeta},
    pressureState: pressureState ? JSON.parse(JSON.stringify(pressureState)) : null,
    // Fall back to live DOM only for the very first snapshot ever taken, when there's
    // no prior generation to have recorded sliders for.
    sliders: lastGeneratedSliders || captureSliders()
  });
  if (history.length > 15) history.shift();
  const btn = document.getElementById('undoBtn'); if (btn) btn.disabled = false;
}
function undoLast(){
  if (!history.length) return;
  const prev = history.pop();
  state = prev.state; charMeta = prev.charMeta;
  pressureState = prev.pressureState || null;
  restoreSliders(prev.sliders);
  lastGeneratedSliders = prev.sliders; // the restored state now corresponds to these again
  document.getElementById('charName').value = charMeta.name || "";
  document.getElementById('charAge').value = charMeta.age || "";
  document.getElementById('charContext').value = charMeta.context || "";
  document.getElementById('archetypeTag').textContent = charMeta.archetypeLabel || "";
  document.getElementById('pressureSheet').style.display = pressureState ? "block" : "none";
  diffLog = {}; rerollExclusions = {}; whyOpen = {};
  onSliderChange();
  renderSheet(); checkConflicts();
  document.getElementById('undoBtn').disabled = history.length === 0;
}

function pickVerbositySlot(verbLevel, rarityPref){
  // Crossover narrowed from ±0.3 (raw ±15) to ±0.12 (raw ±6): the old dead band
  // meant nearly a third of the slider produced identical pacing-pool draws.
  const target = targetFromLevel(verbLevel);
  if (verbLevel <= -0.12){
    const pool = byFilter(AXES.verbosityLow.section, AXES.verbosityLow.category);
    return {slotId:"verbosity", locked:false, label:"Verbosity (minimal-leaning)", target, trait: pickInRange(pool, rarityPref, target)};
  } else if (verbLevel >= 0.12){
    const pool = byFilter(AXES.verbosityHigh.section, AXES.verbosityHigh.category);
    return {slotId:"verbosity", locked:false, label:"Verbosity (high-volume-leaning)", target, trait: pickInRange(pool, rarityPref, target)};
  } else {
    // Dead centre now means "situational pacing at low intensity" rather than an
    // unfiltered free-for-all — the neutral band respects the range engine too.
    const pool = byFilter(AXES.pacing.section, AXES.pacing.category);
    const t = targetFromMag(18);
    return {slotId:"verbosity", locked:false, label:"Verbosity (pacing-driven)", target:t, trait: pickInRange(pool, rarityPref, t)};
  }
}
function pickRegisterSlot(regLevel, rarityPref){
  const target = targetFromLevel(regLevel);
  if (regLevel >= 0.12){
    const pool = byFilter(AXES.stylized.section, AXES.stylized.category);
    return {slotId:"register", locked:false, label:"Register (elaborate-leaning)", target, trait: pickInRange(pool, rarityPref, target)};
  } else if (regLevel <= -0.12){
    const plainPool = byFilter("Vocabulary Traits","Directness & Literalness")
      .concat(byFilter("Vocabulary Traits","Register & Formality Spectrum").filter(t=>/coarse|colloquial|vernacular|elementary|sermo|plain|casual|slang|shop-floor|locker-room|backroom|unpolished|reflexively casual|under-speak/i.test(t.trait)));
    const pool = plainPool.length ? plainPool : byFilter("Vocabulary Traits","Register & Formality Spectrum");
    return {slotId:"register", locked:false, label:"Register (plain-leaning)", target, trait: pickInRange(pool, rarityPref, target)};
  } else {
    const pool = byFilter("Vocabulary Traits","Register & Formality Spectrum");
    const t = targetFromMag(18);
    return {slotId:"register", locked:false, label:"Register (neutral)", target:t, trait: pickInRange(pool, rarityPref, t)};
  }
}
// Shared by pickVocabSlots/pickGrammarSlot/pickMannerSlots: when a category was actually
// boosted by the matrix (something specific is driving this pick), lean the trait choice
// within that category toward higher intensity too — not just which category gets picked.
// An unboosted category (weight 0, arrived at by plain random weighting) skips this so a
// truly neutral pick doesn't get artificially pushed toward extremes.
function pickFromCategoryIntensityAware(section, category, boostMap, rarityPref){
  const pool = byFilter(section, category);
  const strength = (boostMap && boostMap.get(category)) || 0;
  // No signal pointing here: keep it an unsteered draw, mid-scale, so genuinely
  // random slots don't get shoved toward the extremes by accident.
  if (strength <= 0) return {trait: pickInRange(pool, rarityPref, targetFromMag(45), 8), target: targetFromMag(45), steered:false};
  // Boost strength is roughly 0..2 in practice; map it across the full scale so a
  // strongly-driven category yields a correspondingly strong trait.
  const target = targetFromMag(clamp(strength / 2, 0, 1) * 100);
  return {trait: pickInRange(pool, rarityPref, target), target, steered:true};
}

function pickVocabSlots(archetypePref, verbLevel, regLevel, rarityPref, count, profileCats, overrides){
  const boosted = boostedVocabCats(verbLevel, regLevel, profileCats, overrides);
  const pool = archetypePref && archetypePref.length ? archetypePref : VOCAB_CATS;
  const targetCount = count || 2;
  const chosenCats = []; const usedCats = new Set();
  // BUG FIX: this loop had no attempt cap, so with an unlucky weighted draw it
  // could spin for a long time; and its `else if` branch was unreachable because
  // the loop condition already excluded that case, meaning asking for more vocab
  // slots than there are categories silently returned fewer.
  let attempts = 0;
  while (chosenCats.length < targetCount && attempts < 200){
    attempts++;
    const c = pickCategoryWeighted(pool, boosted);
    if (!usedCats.has(c)) { usedCats.add(c); chosenCats.push(c); }
    else if (usedCats.size >= pool.length) { chosenCats.push(c); }
  }
  return chosenCats.map((c,i)=>{
    const r = pickFromCategoryIntensityAware("Vocabulary Traits", c, boosted, rarityPref);
    return {slotId:"vocab"+i, locked:false, label:"Vocabulary — "+c, target:r.target, steered:r.steered, trait:r.trait};
  });
}
function pickGrammarSlot(verbLevel, compLevel, regLevel, rarityPref, profileCats, overrides){
  const boosted = boostedGrammarCats(verbLevel, compLevel, regLevel, profileCats, overrides);
  const c = pickCategoryWeighted(GRAMMAR_CATS, boosted);
  const r = pickFromCategoryIntensityAware("Dialogue Grammar Traits", c, boosted, rarityPref);
  return {slotId:"grammar", locked:false, label:"Dialogue Grammar — "+c, target:r.target, steered:r.steered, trait:r.trait};
}
function pickMannerSlots(count, compLevel, regLevel, rarityPref, forcePool, profileCats, overrides){
  const boosted = boostedMannerCats(compLevel, regLevel, profileCats, overrides);
  // BUG FIX: the stress variant passes VOLATILE_MANNER_CATS.concat(MANNER_CATS),
  // which contains duplicates. Those broke the `usedCats.size >= cats.length`
  // exhaustion check (it could never be true), so requesting more mannerisms than
  // there are distinct categories silently returned fewer. Dedupe up front and
  // let the weighting, not repeated array entries, express the volatile bias.
  const cats = [...new Set(forcePool || MANNER_CATS)];
  if (forcePool) VOLATILE_MANNER_CATS.forEach(c=>{
    if (cats.includes(c)) boosted.set(c, Math.max(boosted.get(c)||0, 1.2));
  });
  const chosenCats = []; const usedCats = new Set();
  let attempts = 0;
  while (chosenCats.length < count && attempts < 200){
    attempts++;
    const c = pickCategoryWeighted(cats, boosted);
    if (!usedCats.has(c)) { usedCats.add(c); chosenCats.push(c); }
    else if (usedCats.size >= cats.length) { chosenCats.push(c); }
  }
  return chosenCats.map((c,i)=>{
    const r = pickFromCategoryIntensityAware("Mannerisms", c, boosted, rarityPref);
    return {slotId:"manner"+i, locked:false, label:"Mannerism — "+c, target:r.target, steered:r.steered, trait:r.trait};
  });
}

/* ================= APPEARANCE CRAFTER =================
   Same engine, new domain. Three dedicated sliders map to pos/neg category pairs
   with continuous intensity, exactly like personality axes:
     Stature:  + Build - Imposing      / - Build - Slight
     Upkeep:   + Upkeep - Immaculate   / - Upkeep - Unkempt
     Presence: + Presence - Striking   / - Presence - Unremarkable
   Movement & Bearing is deliberately NOT its own slider: it draws from the existing
   Activeness personality axis, so a sedentary character moves like one - appearance
   stays causally downstream of who the character is, same as voice. Distinguishing
   Marks draws at the Presence magnitude: the more striking the design intent, the
   stronger the mark. Near-centre sliders (|raw| < 8) skip their slot entirely,
   so an untouched appearance panel adds only Movement + a mild Mark. */
const APPEARANCE_AXES = [
  {id:"stature",  label:"Stature",  pos:"Build \u2014 Imposing",    neg:"Build \u2014 Slight"},
  {id:"upkeep",   label:"Upkeep",   pos:"Upkeep \u2014 Immaculate", neg:"Upkeep \u2014 Unkempt"},
  {id:"presence", label:"Presence", pos:"Presence \u2014 Striking", neg:"Presence \u2014 Unremarkable"},
];
function pickAppearanceSlots(rarityPref, overrides){
  const out = {};
  APPEARANCE_AXES.forEach((axis,i)=>{
    const el = document.getElementById('app_'+axis.id);
    const raw = el ? parseInt(el.value) : 0;
    if (Math.abs(raw) < 8) return; // centred slider = no statement made = no slot
    const cat = raw >= 0 ? axis.pos : axis.neg;
    const target = targetFromMag(Math.abs(raw));
    const trait = pickInRange(byFilter("Appearance", cat), rarityPref, target);
    if (trait) out['app_'+i] = {slotId:'app_'+i, locked:false, label:"Appearance \u2014 "+axis.label, target, trait};
  });
  const actLevel = axisLevel('activeness', overrides);
  const mvTarget = targetFromMag(Math.max(25, Math.abs(actLevel)*50));
  const mv = pickInRange(byFilter("Appearance","Movement & Bearing"), rarityPref, mvTarget);
  if (mv) out['app_move'] = {slotId:'app_move', locked:false, label:"Appearance \u2014 Movement & Bearing", target:mvTarget, trait:mv};
  const pEl = document.getElementById('app_presence');
  const pMag = pEl ? Math.abs(parseInt(pEl.value)) : 0;
  const mkTarget = targetFromMag(Math.max(15, pMag));
  const mk = pickInRange(byFilter("Appearance","Distinguishing Marks"), rarityPref, mkTarget);
  if (mk) out['app_mark'] = {slotId:'app_mark', locked:false, label:"Appearance \u2014 Distinguishing Marks", target:mkTarget, trait:mk};
  return out;
}

// Robustness: one registry of trait ids already placed in the CURRENT build, so
// multi-trait sections (profile depth, doubled personality axes) never seat the
// same trait twice on one sheet. Reset per build; consulted by the multi-draw paths.
let _buildUsedIds = new Set();
function _markUsed(t){ if (t) _buildUsedIds.add(t.id); }
function _drawUnique(fn, tries){
  // Re-draw through the picker's own weighting until we get an unused trait,
  // giving up gracefully (returning the last candidate) if the pool is thin.
  let cand = null;
  for (let i = 0; i < (tries || 24); i++){
    cand = fn();
    if (!cand) return null;
    if (!_buildUsedIds.has(cand.id)) return cand;
  }
  return cand;
}

function buildCharacterState(opts){
  _buildUsedIds = new Set();
  const {verbLevel, regLevel, compLevel, mannerCount, rarityPref, vocabPref, personalityOverrides, vocabCount, forcedProfileCats} = opts;
  // Fold the ACTUAL verb/reg/comp levels this build is using into the override map,
  // rather than trusting whatever the single-character DOM sliders currently show.
  // Without this, cast members and foils — which each carry their OWN randomized or
  // negated voice levels — would have their profile-section resolution (stress, role,
  // values, attachment, humor, vices) silently driven by the main UI's sliders instead
  // of their own. Also sets the live signal vector every pickInRange() call in this
  // build reads for trait-level polarity affinity (see VOICE_AXES / polarityFit above).
  const fullOverrides = Object.assign({}, personalityOverrides, {
    verbosity: Math.round(clamp(verbLevel,-2,2)*50),
    register:  Math.round(clamp(regLevel,-2,2)*50),
    composure: Math.round(clamp(compLevel,-2,2)*50),
  });
  setAffinityVec(fullOverrides);
  // Decide WHO they are first (motivation-adjacent facts), then let that inform HOW they speak.
  const resolvedCats = resolveProfileCategories(rarityPref, fullOverrides, forcedProfileCats);
  // Group toggles: users generating only one kind of content (just a voice, just a
  // psychology, just an appearance) can switch whole blocks off. Profile sections
  // already have per-section toggles; these cover the rest. Unchecked = skipped
  // entirely, not hidden — the slots simply don't exist on the sheet.
  const on = id => { const el = document.getElementById(id); return !el || el.checked; };
  const slots = [];
  if (on('genSpeech')){
    slots.push(pickVerbositySlot(verbLevel, rarityPref));
    slots.push(pickRegisterSlot(regLevel, rarityPref));
    slots.push(pickGrammarSlot(verbLevel, compLevel, regLevel, rarityPref, resolvedCats, fullOverrides));
  }
  if (on('genVocab')) slots.push(...pickVocabSlots(vocabPref, verbLevel, regLevel, rarityPref, vocabCount, resolvedCats, fullOverrides));
  if (on('genManner')) slots.push(...pickMannerSlots(mannerCount, compLevel, regLevel, rarityPref, null, resolvedCats, fullOverrides));
  const obj = {}; slots.forEach(s => obj[s.slotId] = s);
  if (on('genPersonality')) Object.assign(obj, pickPersonalitySlots(rarityPref, fullOverrides));
  Object.assign(obj, pickProfileSlots(rarityPref, resolvedCats));
  if (on('genAppearance')) Object.assign(obj, pickAppearanceSlots(rarityPref, fullOverrides));
  return obj;
}

function buildStressVariant(baseVerbLevel, baseRegLevel, mannerCount, rarityPref){
  // stress pushes composure to extreme volatile, verbosity toward its more urgent extreme
  const stressCompLevel = 2;
  const stressVerbLevel = baseVerbLevel >= 0 ? Math.max(baseVerbLevel, 1.5) : Math.min(baseVerbLevel, -1.5);
  // Under-pressure picks should reflect the EXAGGERATED stress levels, not the calm
  // baseline ones — otherwise a character's pressure sheet would use ordinary-mood
  // trait affinity even though the whole point of this sheet is what changes under load.
  setAffinityVec({
    verbosity: Math.round(clamp(stressVerbLevel,-2,2)*50),
    register:  Math.round(clamp(baseRegLevel,-2,2)*50),
    composure: Math.round(clamp(stressCompLevel,-2,2)*50),
  });

  let pacingPool = byFilter(AXES.pacing.section, AXES.pacing.category).filter(t => STRESS_KEYWORDS.test(t.trait+" "+t.desc));
  if (!pacingPool.length) pacingPool = byFilter(AXES.pacing.section, AXES.pacing.category);
  const verbositySlot = {slotId:"verbosity", locked:false, label:"Verbosity (under pressure)", trait: pickWeighted(pacingPool, rarityPref)};

  const registerSlot = pickRegisterSlot(baseRegLevel, rarityPref);
  registerSlot.label = "Register (under pressure)";

  const currentProfileCats = {};
  PROFILE_SECTIONS.forEach(ps=>{ const s = state["prof_"+ps.id+"_0"]; if (s) currentProfileCats[ps.id] = s.trait.category; });
  const grammarSlot = pickGrammarSlot(stressVerbLevel, stressCompLevel, baseRegLevel, rarityPref, currentProfileCats);
  const mannerSlots = pickMannerSlots(mannerCount, stressCompLevel, baseRegLevel, rarityPref, VOLATILE_MANNER_CATS.concat(MANNER_CATS), currentProfileCats);

  const obj = {};
  [verbositySlot, registerSlot, grammarSlot, ...mannerSlots].forEach((s,i)=>{
    // renumber manner slots to avoid collision with base state keys when rendering separately
    obj[s.slotId.startsWith('manner') ? 'p_'+s.slotId : s.slotId] = s;
  });
  return obj;
}

// ---------- Constraint mode UI ----------
function refreshConstraintChips(){
  const box = document.getElementById('constraintChips');
  if (!box) return;
  const byId = new Map(TRAITS.map(t=>[t.id,t]));
  let h = "";
  bannedCategories.forEach(c=> h += `<span class="chip chip-ban">never: ${c} <b onclick="removeBan('cat','${c.replace(/'/g,"\\'")}')">×</b></span>`);
  categoryTiers.forEach((tier,c)=> h += `<span class="chip ${tier==='prefer'?'chip-req':'chip-tier'}">${tier}: ${c} <b onclick="removeTier('${c.replace(/'/g,"\\'")}')">×</b></span>`);
  bannedTraitIds.forEach(id=>{ const t=byId.get(id); if(t) h += `<span class="chip chip-ban">never: ${t.trait} <b onclick="removeBan('trait','${id}')">×</b></span>`; });
  requiredTraitIds.forEach(id=>{ const t=byId.get(id); if(t) h += `<span class="chip chip-req">always: ${t.trait} <b onclick="removeReq('${id}')">×</b></span>`; });
  box.innerHTML = h || '<span class="sub" style="margin:0;">No constraints active.</span>';
}
function addCategoryBan(){
  const sel = document.getElementById('banCategorySelect');
  if (sel && sel.value){ bannedCategories.add(sel.value); sel.value=""; refreshConstraintChips(); }
}
function addTraitConstraint(mode){
  const inp = document.getElementById('constraintTraitSearch');
  const val = (inp.value||"").trim().toLowerCase();
  if (!val) return;
  const t = TRAITS.find(x=> x.trait.toLowerCase() === val) ||
            TRAITS.find(x=> x.trait.toLowerCase().includes(val));
  if (!t){ alert("No trait matches that name."); return; }
  if (mode === 'ban'){ bannedTraitIds.add(t.id); }
  else { if (!requiredTraitIds.includes(t.id)) requiredTraitIds.push(t.id); }
  inp.value = ""; refreshConstraintChips();
}
function removeBan(kind, key){
  if (kind==='cat') bannedCategories.delete(key); else bannedTraitIds.delete(parseInt(key));
  refreshConstraintChips();
}
function removeReq(id){ requiredTraitIds = requiredTraitIds.filter(x=>x!==parseInt(id)); refreshConstraintChips(); }
function clearConstraints(){ bannedCategories.clear(); bannedTraitIds.clear(); requiredTraitIds=[]; categoryTiers.clear(); refreshConstraintChips(); }
function populateBanCategorySelect(){
  let h0 = '';
  CATS_BY_SECTION.forEach((cats, section)=>{
    h0 += `<optgroup label="${section}">` + cats.map(c=>`<option value="${c}">${c}</option>`).join("") + `</optgroup>`;
  });
  const ban = document.getElementById('banCategorySelect');
  if (ban) ban.innerHTML = '<option value="">— pick a category to ban —</option>' + h0;
  const tier = document.getElementById('tierCategorySelect');
  if (tier) tier.innerHTML = '<option value="">— pick a category to weight —</option>' + h0;
}
// After a build, force-insert every required trait as a locked slot. Required
// beats banned if the user sets both on the same trait — an explicit "always"
// is the stronger, more deliberate statement.
function applyRequiredTraits(obj){
  const byId = new Map(TRAITS.map(t=>[t.id,t]));
  requiredTraitIds.forEach((id,i)=>{
    const t = byId.get(id); if (!t) return;
    obj['req_'+i] = {slotId:'req_'+i, locked:true, required:true, label:'Required — '+t.category, trait:t};
  });
  return obj;
}

/* ================= SEEDED / REPRODUCIBLE GENERATION =================
   A seed string makes the entire generation deterministic: same seed + same
   settings = same character, shareable as text. Implemented by swapping
   Math.random for a seeded PRNG for exactly the duration of the build —
   every pick path already routes through Math.random, so nothing is missed.
   Rerolls are intentionally NOT seeded: a reroll is you overriding the dice. */
function hashSeedString(s){
  let h = 2166136261 >>> 0;
  for (let i=0;i<s.length;i++){ h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; }
  return h >>> 0;
}
function mulberry32(a){
  return function(){
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
let lastSeedUsed = null;

/* ================= WEIGHTED CONSTRAINT TIER =================
   Between hard ban and neutral: per-category "prefer" (x3) and "rarely" (x0.25)
   multipliers. Applied inside pickCategoryWeighted — the one place category
   selection happens — so tiers shape WHICH categories resolve without ever
   making anything impossible the way a ban does. */
let categoryTiers = new Map(); // category -> 'prefer' | 'rarely'
function tierMultiplier(cat){
  const t = categoryTiers.get(cat);
  return t === 'prefer' ? 3 : t === 'rarely' ? 0.25 : 1;
}
function addCategoryTier(tier){
  const sel = document.getElementById('tierCategorySelect');
  if (sel && sel.value){ categoryTiers.set(sel.value, tier); sel.value=""; refreshConstraintChips(); }
}
function removeTier(cat){ categoryTiers.delete(cat); refreshConstraintChips(); }

/* ================= RADAR CHART =================
   The 12-axis polarity profile (axisProfile) rendered as SVG. Values are summed
   trait polarity per axis; normalization is against the strongest axis in the
   set being drawn, so shape (which axes dominate) is the signal, not absolute
   magnitude. profiles: [{label, color, prof}] — one polygon each, so the same
   function draws a single character or a full cast overlay. */
function radarSVG(profiles, size){
  size = size || 300;
  // Only the 12 personality codes belong on this chart — AXIS_LABELS also contains
  // voice-polarity codes (volume, formality, pace, mood) used elsewhere, and mixing
  // them in made the radar read as 16 unrelated spokes.
  const axes = Object.values(AXIS_TO_POLCODE);
  const cx = size/2, cy = size/2, R = size/2 - 46;
  let maxV = 1;
  profiles.forEach(p=> axes.forEach(ax=> maxV = Math.max(maxV, Math.abs(p.prof[ax]||0))));
  const pt = (i, v) => {
    const ang = (Math.PI*2*i/axes.length) - Math.PI/2;
    const r = R * (0.5 + 0.5 * clamp(v/maxV, -1, 1)); // centre ring = 0, outer = +max, inner = -max
    return [cx + r*Math.cos(ang), cy + r*Math.sin(ang)];
  };
  let s = `<svg viewBox="0 0 ${size} ${size}" style="max-width:${size}px;width:100%;">`;
  // rings: -max, 0 (emphasised), +max
  [0.25, 0.5, 0.75, 1].forEach(f=>{
    const ring = axes.map((_,i)=>{ const ang=(Math.PI*2*i/axes.length)-Math.PI/2; return `${cx+R*f*Math.cos(ang)},${cy+R*f*Math.sin(ang)}`; }).join(" ");
    s += `<polygon points="${ring}" fill="none" stroke="var(--border)" stroke-width="${f===0.5?1.6:0.7}" ${f===0.5?'stroke-dasharray="3 3"':''}/>`;
  });
  axes.forEach((ax,i)=>{
    const ang = (Math.PI*2*i/axes.length) - Math.PI/2;
    s += `<line x1="${cx}" y1="${cy}" x2="${cx+R*Math.cos(ang)}" y2="${cy+R*Math.sin(ang)}" stroke="var(--border)" stroke-width="0.6"/>`;
    const lx = cx + (R+24)*Math.cos(ang), ly = cy + (R+24)*Math.sin(ang);
    s += `<text x="${lx}" y="${ly}" font-size="8.5" text-anchor="middle" dominant-baseline="middle" fill="var(--muted)">${AXIS_LABELS[ax]}</text>`;
  });
  profiles.forEach(p=>{
    const pts = axes.map((ax,i)=> pt(i, p.prof[ax]||0).join(",")).join(" ");
    s += `<polygon points="${pts}" fill="${p.color}" fill-opacity="0.13" stroke="${p.color}" stroke-width="2"/>`;
  });
  s += `</svg>`;
  return s;
}

/* ================= VOICE FINGERPRINT =================
   One assembled sample paragraph, built from the character's own trait example
   lines so you HEAR the voice immediately. Deterministic per character (seeded
   from the trait ids), so it doesn't reshuffle on every re-render. */
function voiceFingerprint(st, meta){
  const grab = (prefixes) => Object.keys(st)
    .filter(id => prefixes.some(p=>id.startsWith(p)) && st[id] && st[id].trait && st[id].trait.example)
    .map(id => st[id].trait);
  const voice = grab(["verbosity","grammar","vocab"]);
  const manner = grab(["manner"]);
  const pers = grab(["pers_"]);
  if (!voice.length && !manner.length) return "";
  let seed = 7;
  Object.values(st).forEach(s=>{ if (s && s.trait) seed = (seed*31 + s.trait.id) >>> 0; });
  const rng = mulberry32(seed);
  const take = (arr, n) => {
    const pool = arr.slice(); const out = [];
    while (pool.length && out.length < n) out.push(pool.splice(Math.floor(rng()*pool.length),1)[0]);
    return out;
  };
  const bits = [];
  take(voice, 2).forEach(t=> bits.push(t.example));
  take(manner, 1).forEach(t=> bits.push(t.example));
  take(pers, 1).forEach(t=> bits.push(t.example));
  return bits.join("  ");
}

/* ================= DISTANCE FROM THE PREVIOUS GENERATION =================
   The engine already had everything needed to answer "is this actually a different
   character than the last one I made?" — but the signal existed only implicitly, so
   a user could only sense staleness vaguely after many generations rather than see
   it in the moment. This makes it explicit and immediate.

   Two measures, because they answer different questions:
     - trait overlap  : how much of the literal sheet is the same entry again
     - profile overlap: how many resolved categories (Role, Values, Stress, …) repeat
   A character can score low on the first and high on the second — different words,
   same person underneath — which is exactly the failure mode worth surfacing. */
let lastGenerationSignature = null;
function generationSignature(st){
  const traitIds = new Set();
  const cats = new Set();
  Object.values(st).forEach(s=>{
    if (!s || !s.trait) return;
    traitIds.add(s.trait.id);
  });
  PROFILE_SECTIONS.forEach(ps=>{
    const s = st["prof_"+ps.id+"_0"];
    if (s && s.trait) cats.add(ps.id + "=" + s.trait.category);
  });
  return {traitIds, cats};
}
function overlapPct(a, b){
  if (!a.size || !b.size) return null;
  let shared = 0;
  a.forEach(v=>{ if (b.has(v)) shared++; });
  return Math.round(shared / new Set([...a, ...b]).size * 100);
}
const NOVELTY_TIERS = [
  {min:60, label:"Very similar",     note:"Most of this sheet repeats your last character. Try moving a slider group you haven't touched, or switching archetype."},
  {min:35, label:"Somewhat similar", note:"A recognizable overlap with your last character — fine for a variant, thin for a separate cast member."},
  {min:15, label:"Mostly distinct",  note:"Shares a little ground with your last character; reads as its own person."},
  {min:0,  label:"Distinct",         note:"Almost nothing in common with your last character."},
];
function renderNovelty(prevSig, curSig){
  const box = document.getElementById('noveltyReadout');
  if (!box) return;
  if (!prevSig){ box.style.display = 'none'; return; }
  const traitPct = overlapPct(prevSig.traitIds, curSig.traitIds);
  const catPct = overlapPct(prevSig.cats, curSig.cats);
  if (traitPct === null){ box.style.display = 'none'; return; }
  // Rank on the stronger of the two signals: repeating every resolved category is
  // just as much "the same character again" as repeating the literal traits.
  const tier = NOVELTY_TIERS.find(t => Math.max(traitPct, catPct === null ? 0 : catPct) >= t.min);
  box.style.display = 'block';
  box.className = 'noveltyBox novelty-' + tier.label.split(' ')[0].toLowerCase();
  box.innerHTML =
    `<b>${tier.label} to your last generation</b> — ${traitPct}% of traits shared` +
    (catPct === null ? "" : `, ${catPct}% of resolved profile categories shared`) +
    `. <span class="noveltyNote">${tier.note}</span>`;
}

/* ================= DISTANCE FROM ARCHETYPE =================
   How far the generated sheet actually drifted from its archetype seed. For each
   axis the archetype takes a position on, compare its intended direction+strength
   against the sheet's realised trait-polarity sum. 100% = every archetype axis
   realised in the intended direction at proportional strength; drift comes from
   your slider blend, the dice, and rerolls — all legitimate, which is why this is
   a meter and not a warning. */
function archetypeFidelity(st, arch){
  if (!arch || !arch.pers) return null;
  const prof = axisProfile(st);
  let total = 0, score = 0;
  Object.entries(arch.pers).forEach(([axisId, target])=>{
    const code = AXIS_TO_POLCODE[axisId];
    if (!code || Math.abs(target) < 10) return;
    const want = Math.sign(target);
    const got = prof[code] || 0;
    total++;
    if (Math.sign(got) === want) score += Math.min(1, Math.abs(got)/2); // direction right, credit scales with strength
    else if (got === 0) score += 0.35; // silent on this axis: partial credit
  });
  if (!total) return null;
  return Math.round(100 * score / total);
}

function generateCharacter(){
  snapshotHistory();
  diffLog = {};
  // Per-slot UI state belongs to the previous character, not this one.
  rerollExclusions = {};
  whyOpen = {};
  lastDepthUntouched = [];
  // Depth-first mode: resolve wound/values/attachment/stress first, derive sliders from them.
  const depthFirst = document.getElementById('depthFirstToggle');
  if (depthFirst && depthFirst.checked) applyDepthFirst();

  const archKey = document.getElementById('archetypeSelect').value;
  const arch = ARCHETYPES[archKey] || CUSTOM_ARCHETYPES[archKey];
  // BUG FIX: this used to WRITE the blended value back into the slider elements.
  // Because the blend reads the slider it just wrote, pressing Generate repeatedly
  // with an archetype selected pulled the sliders further toward the archetype each
  // time until the user's own settings were gone — and there was no way to get them
  // back. Compute the blend as a per-generation override instead and leave the
  // controls exactly where the user put them.
  let archOverrides = null;
  if (arch && arch.pers){
    archOverrides = {};
    PERSONALITY_AXES.forEach(a=>{
      const el = document.getElementById('pers_'+a.id);
      const current = el ? parseInt(el.value) : 0;
      archOverrides[a.id] = (arch.pers[a.id] !== undefined)
        ? Math.round(clamp(current*0.35 + arch.pers[a.id]*0.65, -100, 100))
        : current;
    });
  }
  let verbLevel = rawToLevel(intVal('verbositySlider', 0));
  let regLevel = rawToLevel(intVal('registerSlider', 0));
  let compLevel = rawToLevel(intVal('composureSlider', 0));
  if (arch){
    // Built-in archetypes store small hand-tuned deltas (-1/0/1/2) meant to nudge the
    // current slider. Custom archetypes instead capture the exact slider level at save
    // time, so adding it on top of an already-nonzero slider double-counted. Blend both
    // the same way personality already does, rather than treating one as additive.
    const isCustom = archKey.startsWith('custom_');
    verbLevel = isCustom ? clamp(verbLevel*0.35 + arch.verbosity*0.65, -2, 2) : clamp(verbLevel + arch.verbosity, -2, 2);
    regLevel  = isCustom ? clamp(regLevel*0.35  + arch.register*0.65,  -2, 2) : clamp(regLevel  + arch.register,  -2, 2);
    compLevel = isCustom ? clamp(compLevel*0.35 + arch.composure*0.65, -2, 2) : clamp(compLevel + arch.composure, -2, 2);
  }
  const mannerCount = intVal('mannerCount', 3);
  const vocabCount = intVal('vocabCount', 2);
  const rarityPref = document.getElementById('rarityPref').value;

  // Seeded build: swap the RNG for exactly the build's duration, restore in finally.
  const seedInput = document.getElementById('seedInput');
  const seedStr = seedInput ? seedInput.value.trim() : "";
  const seedNum = seedStr ? hashSeedString(seedStr) : ((Date.now() ^ (Math.random()*0x7fffffff)) >>> 0);
  lastSeedUsed = seedStr || seedNum.toString(36);
  const _origRandom = Math.random;
  let newState0, newState;
  try {
    Math.random = mulberry32(seedNum);
    rollCharacterVariants(); // inside the seeded block, so seeds reproduce variants too
    newState0 = buildCharacterState({verbLevel, regLevel, compLevel, mannerCount, rarityPref,
      vocabPref: arch?arch.vocabPref:null, vocabCount, personalityOverrides: archOverrides});
    newState = applyRequiredTraits(applyPinnedTargets(newState0, rarityPref));
  } finally {
    Math.random = _origRandom;
  }
  charMetaSeed = lastSeedUsed;
  const seedOut = document.getElementById('lastSeedReadout');
  if (seedOut) seedOut.textContent = "Seed: " + lastSeedUsed;
  Object.keys(state).forEach(id=>{
    if (state[id] && state[id].locked && newState[id] !== undefined) newState[id] = state[id];
  });
  state = newState;
  // Record which slider positions produced this state, so a future undo (which
  // restores the state that came BEFORE the next generation) can also restore
  // the sliders that actually match it.
  lastGeneratedSliders = captureSliders();

  charMeta = {
    name: document.getElementById('charName').value || "Unnamed Character",
    age: document.getElementById('charAge').value,
    context: document.getElementById('charContext').value,
    archetypeLabel: archKey ? document.getElementById('archetypeSelect').selectedOptions[0].textContent : "Custom random",
    seed: charMetaSeed
  };
  charMeta.archFidelity = arch ? archetypeFidelity(state, arch) : null;
  const emergent = emergentArchetypeName(state);
  if (emergent && !archKey) charMeta.archetypeLabel = emergent.name + (emergent.exact ? "" : " *");
  document.getElementById('archetypeTag').textContent = charMeta.archetypeLabel;

  if (document.getElementById('stressToggle').checked){
    pressureState = buildStressVariant(verbLevel, regLevel, mannerCount, rarityPref);
    document.getElementById('pressureSheet').style.display = "block";
  } else {
    pressureState = null;
    document.getElementById('pressureSheet').style.display = "none";
  }

  // Compare against the PREVIOUS generation before overwriting the stored signature,
  // so the readout answers "how different is this from the last one I made".
  const curSignature = generationSignature(state);
  renderNovelty(lastGenerationSignature, curSignature);
  lastGenerationSignature = curSignature;

  const sheetEl = document.getElementById('sheet');
  const wasHidden = !sheetEl.classList.contains('show');
  renderSheet(); checkConflicts();
  // QoL: on the FIRST generation the result appears far below the controls and it
  // wasn't obvious anything happened. Scroll it into view once; on regenerations
  // the user has usually positioned themselves and we leave scroll alone.
  if (wasHidden && typeof sheetEl.scrollIntoView === 'function') sheetEl.scrollIntoView({behavior:'smooth', block:'start'});
}

function rerollSlot(slotId){
  const old = state[slotId];
  // BUG FIX: snapshotHistory() ran before the lock check and before validating the
  // slot, so rerolling a locked (or missing) slot pushed a junk no-op entry onto
  // the undo stack. Validate first, snapshot only once we know we'll change something.
  if (!old || !old.trait || old.locked) return;
  snapshotHistory();
  const rarityPref = document.getElementById('rarityPref').value;
  // Reroll always operates on the single main-character UI, so the live DOM sliders
  // ARE the correct source for trait-level polarity affinity here (no per-call
  // overrides needed, unlike cast/foil generation).
  setAffinityVec(null);

  // Remember what we're rejecting so repeated rerolls stop cycling back to it.
  // BUG FIX: exclusions were keyed on the trait NAME, but several trait names are
  // reused across sections ("Deflect-with-humour", "Slightly reserved"), so passing
  // on one silently blacklisted unrelated traits elsewhere. Key on id.
  if (!rerollExclusions[slotId]) rerollExclusions[slotId] = new Set();
  rerollExclusions[slotId].add(old.trait.id);
  const excluded = rerollExclusions[slotId];
  // Re-draw up to a bounded number of times rather than filtering the pool, because
  // the pick functions own their own weighting/intensity logic and we don't want to
  // duplicate it here. If a category is nearly exhausted we give up and allow a
  // repeat rather than looping forever or returning nothing.
  const drawFresh = (fn) => {
    let cand = null;
    for (let i = 0; i < 32; i++){
      cand = fn();
      if (!cand || !cand.trait) break;
      if (!excluded.has(cand.trait.id)) return cand;
    }
    return cand;
  };
  const rawOf = id => { const el = document.getElementById(id); return el ? parseInt(el.value) : 0; };

  let replacement;
  if (pinnedTargets[slotId] !== undefined){
    // Pinned slots reroll around their own pinned target, ignoring whatever the
    // driving slider currently says — same section/category as before, different
    // trait, same intensity neighbourhood.
    const tgt = pinnedTargets[slotId];
    const pool = byFilter(old.trait.section, old.trait.category);
    replacement = drawFresh(()=>({slotId, locked:false, label: old.label, sectionId: old.sectionId,
      target:tgt, pinned:true, trait: pickInRange(pool, rarityPref, tgt, 3)}));
  } else if (slotId === "verbosity"){
    replacement = drawFresh(()=>pickVerbositySlot(rawToLevel(rawOf('verbositySlider')), rarityPref));
  } else if (slotId === "register"){
    replacement = drawFresh(()=>pickRegisterSlot(rawToLevel(rawOf('registerSlider')), rarityPref));
  } else if (slotId === "grammar"){
    const currentProfileCats = {};
    PROFILE_SECTIONS.forEach(ps=>{ const s = state["prof_"+ps.id+"_0"]; if (s && s.trait) currentProfileCats[ps.id] = s.trait.category; });
    replacement = drawFresh(()=>pickGrammarSlot(
      rawToLevel(rawOf('verbositySlider')),
      rawToLevel(rawOf('composureSlider')),
      rawToLevel(rawOf('registerSlider')), rarityPref, currentProfileCats));
  } else if (slotId.startsWith("vocab")){
    // Rerolls now honour the slot's own intensity target, so a reroll stays inside
    // the band the sliders asked for instead of dropping back to a flat random draw.
    const cat = old.trait.category, tgt = old.target;
    replacement = drawFresh(()=>({slotId, locked:false, label: old.label, target:tgt, steered:old.steered,
      trait: pickInRange(byFilter("Vocabulary Traits", cat), rarityPref, tgt)}));
  } else if (slotId.startsWith("manner")){
    const cat = old.trait.category, tgt = old.target;
    replacement = drawFresh(()=>({slotId, locked:false, label: old.label, target:tgt, steered:old.steered,
      trait: pickInRange(byFilter("Mannerisms", cat), rarityPref, tgt)}));
  } else if (slotId.startsWith("prof_")){
    const cat = old.trait.category;
    const pool = byFilter(old.trait.section, cat);
    const tgt = profileTarget();
    replacement = drawFresh(()=>({slotId, locked:false, label: old.label, sectionId: old.sectionId, target:tgt,
      trait: pickInRange(pool, rarityPref, tgt)}));
  } else if (slotId.startsWith("pers_")){
    const axisId = slotId.replace("pers_","").replace(/__2$/,"");
    const axis = PERSONALITY_AXES.find(a=>a.id===axisId);
    if (axis) replacement = drawFresh(()=>pickPersonalitySlot(axis, rawToLevel(rawOf('pers_'+axisId)), rarityPref));
  }
  // BUG FIX: an unrecognised slotId (or an exhausted pool) left `replacement`
  // undefined, and this assigned it straight into state — blanking the slot and
  // throwing on the next render. Bail out instead and leave the slot intact.
  if (!replacement || !replacement.trait){ history.pop(); return; }
  if (old.trait.id !== replacement.trait.id){
    diffLog[slotId] = {from: old.trait.trait, to: replacement.trait.trait};
  }
  state[slotId] = replacement;
  renderSheet(); checkConflicts();
}

function toggleWhy(slotId){ whyOpen[slotId] = !whyOpen[slotId]; renderSheet(); }
function clearExclusions(slotId){
  delete rerollExclusions[slotId];
  renderSheet();
}
function dismissDiff(slotId){ delete diffLog[slotId]; renderSheet(); }

function toggleLock(slotId){
  if (state[slotId]) { state[slotId].locked = !state[slotId].locked; renderSheet(); }
}
function lockAll(){
  Object.values(state).forEach(s=>{ if (s && s.trait) s.locked = true; });
  renderSheet();
}
function unlockAll(){
  Object.values(state).forEach(s=>{ if (s) s.locked = false; });
  renderSheet();
}

/* ================= PIN INTENSITY =================
   Distinct from lock. Lock freezes the exact trait. Pin freezes the *target*
   this slot draws toward — regeneration and reroll keep landing near that
   intensity level even as sliders elsewhere move around, but the actual trait
   is still free to vary. Lets you say "this mannerism stays roughly this
   intense" while everything else about the character keeps shifting. */
function togglePin(slotId){
  const s = state[slotId];
  if (!s || !s.trait) return;
  if (pinnedTargets[slotId] !== undefined){
    delete pinnedTargets[slotId];
  } else {
    pinnedTargets[slotId] = clamp((typeof s.target === 'number') ? s.target : traitPos(s.trait), 1, 5);
  }
  renderSheet();
}
function adjustPin(slotId, delta){
  if (pinnedTargets[slotId] === undefined) return;
  pinnedTargets[slotId] = clamp(pinnedTargets[slotId] + delta, 1, 5);
  setAffinityVec(null); // live DOM sliders — this always operates on the main character
  // Re-draw immediately so the pin control feels responsive rather than only
  // taking effect on the next full generate/reroll.
  const s = state[slotId];
  if (s && s.trait){
    const pool = byFilter(s.trait.section, s.trait.category);
    const rarityPref = document.getElementById('rarityPref').value;
    const picked = pickInRange(pool, rarityPref, pinnedTargets[slotId], 3);
    if (picked && picked.id !== s.trait.id){ diffLog[slotId] = {from:s.trait.trait, to:picked.trait}; }
    if (picked){ state[slotId] = {...s, target: pinnedTargets[slotId], pinned:true, trait: picked}; }
    else { state[slotId].target = pinnedTargets[slotId]; state[slotId].pinned = true; }
  }
  renderSheet();
}
function unpinAll(){ pinnedTargets = {}; renderSheet(); }

// Applied after a fresh buildCharacterState (before lock-merge, so lock still wins):
// for every slot with a pin, redraw within the SAME section/category the fresh build
// picked, but targeting the pinned intensity rather than whatever the sliders would
// have produced. Also drops pins whose slot no longer exists (section disabled, etc.)
// so they don't linger invisibly.
function applyPinnedTargets(obj, rarityPref){
  Object.keys(pinnedTargets).forEach(slotId=>{
    const cur = obj[slotId];
    if (!cur || !cur.trait){ delete pinnedTargets[slotId]; return; }
    const pool = byFilter(cur.trait.section, cur.trait.category);
    const tgt = pinnedTargets[slotId];
    const picked = pickInRange(pool, rarityPref, tgt, 3);
    obj[slotId] = {...cur, target: tgt, pinned: true, trait: picked || cur.trait};
  });
  return obj;
}

function intensityDots(n){ return "●".repeat(n) + "○".repeat(5-n); }

// Color-coded wayfinding: every group heading gets a fixed accent so the same kind of
// trait always reads the same color, wherever it appears in the app.
const SECTION_COLORS = {
  "Personality": "var(--bubblegum)",
  "Speech Pattern": "var(--dusk-blue)",
  "Speech Under Pressure": "var(--dusk-blue)",
  "Vocabulary": "var(--emerald-deep)",
  "Mannerisms": "var(--golden-deep)",
  "Mannerisms Under Pressure": "var(--golden-deep)",
  "Motivation & Wound": "var(--bubblegum)",
  "Conflict & Stress Response": "var(--dusk-blue)",
  "Social Role in a Group": "var(--emerald-deep)",
  "Values & Moral Line": "var(--golden-deep)",
  "Attachment & Intimacy": "var(--bubblegum)",
  "Humor Style": "var(--dusk-blue)",
  "Habits & Vices": "var(--emerald-deep)",
};
SECTION_COLORS["Appearance"] = "#8a6bbf";
SECTION_COLORS["Required (constraints)"] = "#b8860b";
function sectionColor(title){ return SECTION_COLORS[title] || "var(--dusk-blue)"; }

// Trait frequency budget: how often an assigned trait should actually surface in prose.
const FREQ_BUDGET = {
  1: {label:"once or twice, whole book", hint:"A flicker. If it shows up more than twice it stops reading as subtle."},
  2: {label:"once a chapter",            hint:"Occasional colour. Enough to notice, not enough to characterise."},
  3: {label:"a few times a chapter",     hint:"Recognisable. A reader could describe this trait after a chapter or two."},
  4: {label:"most scenes",               hint:"Load-bearing. This is one of the two or three things that define the voice."},
  5: {label:"nearly every page",         hint:"Dominant. Overuse is the risk here — it can tip into caricature fast."}
};
function freqBudgetHTML(t){
  const b = FREQ_BUDGET[t.intensity] || FREQ_BUDGET[3];
  return `<div class="freqBudget"><b>Use:</b> ${b.label} <span class="freqHint">— ${b.hint}</span></div>`;
}

// The active band: the span of slider magnitudes at which this exact trait is
// eligible. This is the "range value" made visible — outside this window the trait
// cannot be drawn at all, so you can read straight off the card why a setting of 40
// gave you this and a setting of 70 never will.
function bandHTML(t, slot){
  const [lo, hi] = traitBand(t);
  const pos = traitPos(t).toFixed(2);
  const tgt = (slot && typeof slot.target === 'number') ? slot.target : null;
  const onTarget = tgt !== null ? Math.abs(traitPos(t) - tgt) : null;
  const fitTxt = onTarget === null ? "" :
    (onTarget < 0.18 ? " · dead-centre of the current target"
     : onTarget < 0.45 ? " · close to the current target"
     : " · toward the edge of the window");
  return `<div class="bandRow" title="This trait can only be drawn while the driving slider's magnitude sits in this range.">
    <span class="bandLabel">active range</span>
    <span class="bandTrack"><i style="left:${lo}%; width:${Math.max(2,hi-lo)}%;"></i>${tgt!==null?`<b style="left:${magFromPos(tgt)}%;"></b>`:``}</span>
    <span class="bandNums">${lo}–${hi}</span>
    <span class="bandPos">pos ${pos}${fitTxt}</span>
  </div>`;
}

function traitCardHTML(id, s, includeControls, showDiff, accent){
  // BUG FIX: several code paths could produce a slot with a null trait (an empty
  // pool after filtering, a failed reroll), and this function dereferenced it
  // immediately — throwing and blanking the whole sheet. Fail soft on one card.
  if (!s || !s.trait){
    return `<div class="traitCard"><div class="traitMain"><div class="traitDesc" style="opacity:.6">No trait available for this slot at the current settings — widen the slider precision or enable more categories.</div></div></div>`;
  }
  const rarityClass = s.trait.rarity === "signature" ? "signature" : "";
  const lockedClass = s.locked ? "locked" : "";
  const diff = showDiff ? diffLog[id] : null;
  const style = accent ? ` style="--section-accent:${accent}"` : ``;
  return `
    <div class="traitCard"${style}>
      <div class="traitMain">
        <div class="traitName">${s.trait.trait}
          <span class="rarityBadge ${rarityClass}">${s.trait.rarity}</span>
          <span class="intensityDots" title="Intensity ${s.trait.intensity}/5 (continuous position ${traitPos(s.trait).toFixed(2)})">${intensityDots(s.trait.intensity)}</span>
        </div>
        <div class="traitCat">${s.trait.category}</div>
        <div class="traitDesc">${s.trait.desc}</div>
        ${includeControls ? bandHTML(s.trait, s) : ``}
        ${s.trait.example ? `<div class="exampleLine">&ldquo;${s.trait.example}&rdquo;</div>` : ``}
        ${includeControls ? freqBudgetHTML(s.trait) : ``}
        ${diff ? `<div class="diffNote">↺ was: "${diff.from}" <button onclick="dismissDiff('${id}')">dismiss</button></div>` : ``}
        ${includeControls && whyOpen[id] ? `<div class="whyNote">${explainPick(id, s)}${(rerollExclusions[id]&&rerollExclusions[id].size)?`<div class="whyExcl">Excluded from rerolls here: ${rerollExclusions[id].size} trait${rerollExclusions[id].size>1?"s":""} you've already passed on. <button onclick="clearExclusions('${id}')">reset</button></div>`:``}</div>` : ``}
      </div>
      ${includeControls ? `
      <div class="slotBtns">
        <button class="lockBtn ${lockedClass}" onclick="toggleLock('${id}')" title="Keep this trait through rerolls and regeneration">${s.locked ? "locked" : "lock"}</button>
        <div class="pinRow">
          <button class="pinBtn ${pinnedTargets[id]!==undefined ? "pinned" : ""}" onclick="togglePin('${id}')" title="Pin this slot's intensity target (not the exact trait) so future generations/rerolls stay near this level even as sliders move elsewhere">${pinnedTargets[id]!==undefined ? "pinned "+pinnedTargets[id].toFixed(1) : "pin"}</button>
          ${pinnedTargets[id]!==undefined ? `<button class="pinAdj" onclick="adjustPin('${id}',-0.2)" title="Nudge pinned intensity down">−</button><button class="pinAdj" onclick="adjustPin('${id}',0.2)" title="Nudge pinned intensity up">+</button>` : ``}
        </div>
        <button class="rerollBtn" onclick="rerollSlot('${id}')" title="Draw a different trait for this slot (never repeats one you've already rejected here)">reroll</button>
        <button class="whyBtn" onclick="toggleWhy('${id}')" title="Why did I get this trait?">why?</button>
      </div>` : ``}
    </div>`;
}
function titleForSlotId(id){
  if (id.startsWith("app_")) return "Appearance";
  if (id.startsWith("req_")) return "Required (constraints)";
  if (id.startsWith("pers_")) return "Personality";
  if (id.startsWith("prof_")){
    const secId = id.split("_")[1];
    const ps = PROFILE_SECTIONS.find(p=>p.id===secId);
    return ps ? ps.label : "Personality";
  }
  if (id==="verbosity"||id==="register"||id==="grammar") return "Speech Pattern";
  if (id.startsWith("vocab")) return "Vocabulary";
  if (id.startsWith("manner")) return "Mannerisms";
  return "Speech Pattern";
}

function renderSheet(){
  const sheet = document.getElementById('sheet');
  sheet.classList.add('show');
  document.getElementById('sheetTitle').textContent = charMeta.name || "Character Voice";
  const metaBits = [];
  if (charMeta.age) metaBits.push("Age " + charMeta.age);
  if (charMeta.context) metaBits.push(charMeta.context);
  document.getElementById('charMetaLine').textContent = metaBits.join(" · ");

  const body = document.getElementById('sheetBody');
  body.innerHTML = "";
  const profGroups = PROFILE_SECTIONS.map(ps=>({
    title: ps.label,
    ids: Object.keys(state).filter(k=>k.startsWith("prof_"+ps.id+"_"))
  })).filter(g=>g.ids.length);
  const groups = [
    {title:"Required (constraints)", ids:Object.keys(state).filter(k=>k.startsWith("req_"))},
    {title:"Personality", ids:Object.keys(state).filter(k=>k.startsWith("pers_"))},
    ...profGroups,
    {title:"Appearance", ids:Object.keys(state).filter(k=>k.startsWith("app_"))},
    {title:"Speech Pattern", ids:["verbosity","register","grammar"]},
    {title:"Vocabulary", ids:Object.keys(state).filter(k=>k.startsWith("vocab"))},
    {title:"Mannerisms", ids:Object.keys(state).filter(k=>k.startsWith("manner"))},
  ];
  groups.forEach(g=>{
    const validIds = g.ids.filter(id=>state[id]);
    if(!validIds.length) return;
    const div = document.createElement('div');
    div.className = "axisGroup";
    div.style.setProperty('--section-accent', sectionColor(g.title));
    // PERF FIX: innerHTML += inside a loop re-parses the accumulated HTML on every
    // iteration (quadratic), which was the main source of visible lag on large
    // sheets. Build the string once, assign once.
    let inner = `<div class="axisTitle">${g.title}</div>`;
    validIds.forEach(id=>{ inner += traitCardHTML(id, state[id], true, true); });
    div.innerHTML = inner;
    body.appendChild(div);
  });

  // Coherence score + soft tension notes
  const co = coherenceScore(state);
  const tensions = softTensionsFor(state);
  const insight = document.getElementById('insightPanel');
  if (insight){
    let h = "";
    if (co){
      const barColor = co.lift>=25?"var(--emerald)":co.lift>=10?"var(--golden)":"var(--bubblegum)";
      const liftTxt = (co.lift>=0?"+":"") + co.lift;
      h += `<div class="coherenceRow">
        <div class="coherenceLabel">Coherence <b>${co.pct}%</b> <span style="opacity:.7;font-weight:400;">(${liftTxt} vs chance)</span></div>
        <div class="coherenceBar">
          <span style="width:${co.pct}%; background:${barColor};"></span>
          <i class="coherenceBaseline" style="left:${co.basePct}%;" title="Chance baseline for these settings: ${co.basePct}%"></i>
        </div>
      </div><div class="coherenceNote">${co.label} (${co.reinforced} of ${co.total} picks reinforced. A random character with these same settings would score about ${co.basePct}%, so the meaningful number is the ${liftTxt}-point difference.)</div>`;
    }
    if (tensions.length){
      h += `<div class="tensionBlock"><div class="tensionTitle">Uncommon combinations — not errors</div><ul>` +
           tensions.map(t=>`<li>${t}</li>`).join("") + `</ul></div>`;
    }
    const patterns = secondOrderTensions(state);
    if (patterns.length){
      h += `<div class="tensionBlock" style="border-left-color:var(--dusk-blue);"><div class="tensionTitle" style="color:var(--dusk-blue);">Emergent patterns</div>` +
           patterns.map(p=>`<div style="margin:6px 0;"><b>${p.name}.</b> ${p.note}</div>`).join("") + `</div>`;
    }
    // Archetype fidelity meter — only meaningful when an archetype seeded the build.
    if (charMeta.archFidelity !== null && charMeta.archFidelity !== undefined){
      const f = charMeta.archFidelity;
      const col = f>=70?"var(--emerald)":f>=45?"var(--golden)":"var(--bubblegum)";
      h += `<div class="coherenceRow" style="margin-top:10px;">
        <div class="coherenceLabel">Archetype fidelity <b>${f}%</b></div>
        <div class="coherenceBar"><span style="width:${f}%; background:${col};"></span></div>
      </div><div class="coherenceNote">How much of the archetype's intended shape survived your slider blend, the dice, and any rerolls. Drift is legitimate — this is a compass reading, not a grade.</div>`;
    }
    // Voice fingerprint — assembled from the character's own example lines.
    const fp = voiceFingerprint(state, charMeta);
    if (fp){
      h += `<div class="tensionBlock" style="border-left-color:var(--emerald); margin-top:10px;"><div class="tensionTitle" style="color:var(--emerald);">Voice fingerprint</div><div style="font-style:italic; line-height:1.7;">${fp}</div><div class="sub" style="margin:6px 0 0;">Sample lines drawn from this character's own traits — how they'd actually sound on the page. Stable for this exact character; changes when the traits do.</div></div>`;
    }
    // Radar — 12-axis realised polarity shape.
    try {
      const prof = axisProfile(state);
      if (Object.keys(prof).length >= 3){
        h += `<div style="margin-top:12px;"><div class="tensionTitle" style="color:var(--dusk-blue); margin-bottom:4px;">Axis profile</div>${radarSVG([{label:charMeta.name, color:"#4a6b8a", prof}])}
        <div class="sub" style="margin:2px 0 0;">Summed trait polarity per axis. The dashed middle ring is zero; outside it the sheet leans positive on that axis, inside negative. Shape is the signal — which axes dominate — not absolute size.</div></div>`;
      }
    } catch(e){}
    if (lastDepthUntouched.length){
      h += `<div class="depthNote"><b>Depth-first note:</b> no resolved profile category implies ${lastDepthUntouched.join(", ")}, so ${lastDepthUntouched.length>1?"those sliders were":"that slider was"} left exactly as you set ${lastDepthUntouched.length>1?"them":"it"} rather than being reset to centre.</div>`;
    }
    insight.innerHTML = h;
    insight.style.display = h ? "block" : "none";
  }

  if (pressureState){
    const pbody = document.getElementById('pressureBody');
    pbody.innerHTML = "";
    const pgroups = [
      {title:"Speech Under Pressure", ids:["verbosity","register","grammar"]},
      {title:"Mannerisms Under Pressure", ids:Object.keys(pressureState).filter(k=>k.startsWith("p_manner"))},
    ];
    pgroups.forEach(g=>{
      const validIds = g.ids.filter(id=>pressureState[id]);
      if(!validIds.length) return;
      const div = document.createElement('div');
      div.className = "axisGroup";
      div.style.setProperty('--section-accent', sectionColor(g.title));
      let inner = `<div class="axisTitle">${g.title}</div>`;
      validIds.forEach(id=>{ inner += traitCardHTML(id, pressureState[id], false, false); });
      div.innerHTML = inner;
      pbody.appendChild(div);
    });
  }
}

function checkConflicts(){
  const combinedState = {...state};
  const found = checkConflictsFor(combinedState);
  const box = document.getElementById('warnBox');
  if(found.length){
    box.classList.add('show');
    const worst = found[0].tier;
    box.innerHTML = `⚠ Trait tension detected <span class="conflictCount">(${found.length}, most severe: ${worst})</span><ul>` +
      found.map(f=>`<li><span class="conflictTier conflictTier-${f.tier.toLowerCase()}">${f.tier}</span> ${f.text} <span class="conflictNote">${f.tierNote}</span></li>`).join("") +
      "</ul>";
  } else { box.classList.remove('show'); }
}

function sheetToText(st, meta, pState){
  const showEx = document.getElementById('examplesToggle') ? document.getElementById('examplesToggle').checked : true;
  const L = [];

  // ---- Title & meta ----
  L.push(`# ${meta.name || "Unnamed Character"}`);
  const bits = [];
  if (meta.age) bits.push(`**Age:** ${meta.age}`);
  if (meta.context) bits.push(`**Context:** ${meta.context}`);
  if (meta.archetypeLabel) bits.push(`**Archetype:** ${meta.archetypeLabel}`);
  if (bits.length) L.push("", bits.join("  \n"));
  try {
    const co = coherenceScore(st);
    if (co) L.push("", `_Coherence: ${co.pct}% (${co.lift>=0?"+":""}${co.lift} vs a ${co.basePct}% chance baseline) — ${co.label}_`);
    const tn = softTensionsFor(st);
    if (tn.length) L.push("", "**Uncommon combinations:**", ...tn.map(t=>`- ${t}`));
    if (meta.seed) L.push("", `_Seed: ${meta.seed}_`);
    const fp = voiceFingerprint(st, meta);
    if (fp) L.push("", "**Voice fingerprint:** " + fp);
  } catch(e){}

  const fmt = (slot) => {
    const t = slot.trait;
    const out = [`- **${t.trait}** — ${t.desc}`];
    out.push(`  - *${t.category}* · intensity ${t.intensity}/5 · ${t.rarity} · use: ${(FREQ_BUDGET[t.intensity]||FREQ_BUDGET[3]).label}`);
    if (showEx && t.example) out.push(`  - > ${t.example}`);
    return out.join("\n");
  };
  const block = (title, ids) => {
    const valid = ids.filter(id=>st[id]);
    if (!valid.length) return;
    L.push("", `## ${title}`, "");
    valid.forEach(id=> L.push(fmt(st[id])));
  };

  // ---- Required constraints ----
  block("Required (constraints)", Object.keys(st).filter(k=>k.startsWith("req_")));

  // ---- Personality ----
  block("Personality", Object.keys(st).filter(k=>k.startsWith("pers_")));

  // ---- Profile sections (each its own heading) ----
  if (typeof PROFILE_SECTIONS !== 'undefined'){
    PROFILE_SECTIONS.forEach(ps=>{
      block(ps.label, Object.keys(st).filter(k=>k.startsWith("prof_"+ps.id+"_")));
    });
  }

  // ---- Appearance ----
  block("Appearance", Object.keys(st).filter(k=>k.startsWith("app_")));

  // ---- Voice ----
  block("Speech Pattern", ["verbosity","register","grammar"]);
  block("Vocabulary", Object.keys(st).filter(k=>k.startsWith("vocab")));
  block("Mannerisms", Object.keys(st).filter(k=>k.startsWith("manner")));

  // ---- Under pressure ----
  if (pState){
    L.push("", "## Under Pressure", "");
    ["verbosity","register","grammar"].forEach(id=>{ if(pState[id]) L.push(fmt(pState[id])); });
    Object.keys(pState).filter(k=>k.startsWith("p_manner")).forEach(id=> L.push(fmt(pState[id])));
  }

  L.push("", "---", "");
  return L.join("\n");
}

function copyText(text, btn){
  const done = ()=>{ if (btn){ const old = btn.textContent; btn.textContent = "Copied!"; setTimeout(()=>btn.textContent=old, 1200); } };
  // BUG FIX: navigator.clipboard is undefined in non-secure contexts (plain http,
  // file://) — this threw instead of copying. Guard it, and fall back to the
  // textarea/execCommand path so the button works everywhere.
  if (navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).then(done).catch(()=>legacyCopy(text, done));
  } else {
    legacyCopy(text, done);
  }
}
function legacyCopy(text, done){
  try {
    const ta = document.createElement('textarea');
    ta.value = text; ta.style.position='fixed'; ta.style.opacity='0';
    document.body.appendChild(ta); ta.select();
    const ok = document.execCommand && document.execCommand('copy');
    document.body.removeChild(ta);
    if (ok) done(); else alert("Copy failed — your browser may block clipboard access here.");
  } catch(e){ alert("Copy failed — your browser may block clipboard access here."); }
}
function downloadText(text, filename){
  const blob = new Blob([text], {type:"text/markdown;charset=utf-8"});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename; a.click();
  setTimeout(()=>URL.revokeObjectURL(url), 1000);
}
// ---------- Full-fidelity JSON export / import ----------
// The markdown export is for reading; this is for ROUND-TRIPPING. Everything needed
// to restore the exact character — trait state, meta, pressure sheet, pins — in one
// file, importable later or on another machine. This is the first building block of
// the "complete character sheet creator" direction: a portable character format.
const CHAR_FORMAT_VERSION = 1;
function exportCharacterJSON(){
  if (!Object.keys(state).length){ alert("Generate a character first."); return; }
  const payload = {
    format: "character-voice-sheet", version: CHAR_FORMAT_VERSION,
    exported: new Date().toISOString(),
    charMeta, state, pressureState, pinnedTargets, charVariants,
    sliders: captureSliders()
  };
  const name = (charMeta.name || "character").replace(/[^a-z0-9_-]+/gi,'_');
  downloadText(JSON.stringify(payload, null, 2), name + ".character.json");
}
function importCharacterJSON(fileInput){
  const file = fileInput.files && fileInput.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = () => {
    try {
      const p = JSON.parse(reader.result);
      if (p.format !== "character-voice-sheet") throw new Error("Not a character sheet file.");
      // Re-link every imported trait to the live TRAITS pool by id, so imported
      // characters keep working with reroll/pin/why (which need live trait objects)
      // and quietly survive trait-text updates between app versions. Unmatched ids
      // (removed traits) keep their embedded copy, flagged so the user knows.
      const byId = new Map(TRAITS.map(t=>[t.id,t]));
      let orphans = 0;
      const relink = (st)=>{ if(!st) return st;
        Object.values(st).forEach(s=>{
          if (s && s.trait){ const live = byId.get(s.trait.id); if (live) s.trait = live; else orphans++; }
        }); return st; };
      snapshotHistory();
      state = relink(p.state || {});
      pressureState = relink(p.pressureState || null);
      charMeta = p.charMeta || {name:"Imported", age:"", context:"", archetypeLabel:"Imported"};
      pinnedTargets = p.pinnedTargets || {};
      charVariants = p.charVariants || {};
      if (p.sliders) restoreSliders(p.sliders);
      lastGeneratedSliders = p.sliders || null;
      document.getElementById('charName').value = charMeta.name || "";
      document.getElementById('charAge').value = charMeta.age || "";
      document.getElementById('charContext').value = charMeta.context || "";
      document.getElementById('archetypeTag').textContent = charMeta.archetypeLabel || "Imported";
      document.getElementById('pressureSheet').style.display = pressureState ? "block" : "none";
      diffLog = {}; rerollExclusions = {}; whyOpen = {};
      onSliderChange(); renderSheet(); checkConflicts();
      if (orphans) alert(orphans + " trait(s) in this file no longer exist in the app's pool; their saved text was kept as-is.");
    } catch(e){ alert("Could not import: " + e.message); }
    fileInput.value = ""; // allow re-importing the same file
  };
  reader.readAsText(file);
}

// Builds styled HTML for clipboard — pastes as formatted text into Docs/Word/email
// instead of raw markdown syntax. Structure mirrors sheetToText exactly.
function sheetToHTML(st, meta, pState){
  const esc = s => String(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
  let h = `<h1 style="font-family:Georgia,serif;margin:0 0 4px;">${esc(meta.name||"Character Voice")}</h1>`;
  const bits = []; if (meta.age) bits.push("Age "+esc(meta.age)); if (meta.context) bits.push(esc(meta.context));
  if (meta.archetypeLabel) bits.push(esc(meta.archetypeLabel));
  if (bits.length) h += `<p style="color:#666;margin:0 0 14px;">${bits.join(" · ")}</p>`;
  const groupOf = (obj) => {
    const groups = new Map();
    Object.keys(obj).forEach(id=>{
      const s = obj[id]; if (!s || !s.trait) return;
      const title = titleForSlotId(id);
      if (!groups.has(title)) groups.set(title, []);
      groups.get(title).push(s);
    });
    return groups;
  };
  groupOf(st).forEach((slots, title)=>{
    h += `<h2 style="font-family:Georgia,serif;font-size:1.05em;border-bottom:1px solid #ccc;padding-bottom:2px;margin:16px 0 6px;">${esc(title)}</h2>`;
    slots.forEach(s=>{
      h += `<p style="margin:6px 0;"><b>${esc(s.trait.trait)}</b> <span style="color:#888;font-size:.85em;">(${esc(s.trait.category)} · intensity ${s.trait.intensity}/5 · ${esc(s.trait.rarity)})</span><br>${esc(s.trait.desc)}<br><i style="color:#555;">"${esc(s.trait.example)}"</i></p>`;
    });
  });
  if (pState){
    h += `<h2 style="font-family:Georgia,serif;font-size:1.05em;border-bottom:1px solid #ccc;padding-bottom:2px;margin:16px 0 6px;">Under Pressure</h2>`;
    Object.values(pState).forEach(s=>{
      if (!s || !s.trait) return;
      h += `<p style="margin:6px 0;"><b>${esc(s.trait.trait)}</b><br>${esc(s.trait.desc)}<br><i style="color:#555;">"${esc(s.trait.example)}"</i></p>`;
    });
  }
  return h;
}
function copySheet(btnEl){
  const htmlBody = sheetToHTML(state, charMeta, pressureState);
  const plain = sheetToText(state, charMeta, pressureState);
  // Rich-text clipboard: paste lands formatted in Docs/Word/email. Falls back to
  // plain text where ClipboardItem isn't available (older browsers, non-secure
  // contexts), so the button never silently fails.
  const done = ()=>{ if (btnEl){ const o=btnEl.textContent; btnEl.textContent="Copied!"; setTimeout(()=>btnEl.textContent=o,1200);} };
  if (typeof ClipboardItem !== 'undefined' && navigator.clipboard && navigator.clipboard.write){
    const item = new ClipboardItem({
      'text/html': new Blob([htmlBody], {type:'text/html'}),
      'text/plain': new Blob([plain], {type:'text/plain'})
    });
    navigator.clipboard.write([item]).then(done).catch(()=> copyText(plain, btnEl));
  } else {
    copyText(plain, btnEl);
  }
}
function downloadSheet(){
  const fn = (charMeta.name || "character").replace(/[^a-z0-9]+/gi,"_").replace(/^_|_$/g,"") + ".md";
  downloadText(sheetToText(state, charMeta, pressureState), fn);
}

// ================= STORAGE =================
// `window.storage` is the key-value API Anthropic exposes inside Claude-artifact
// sandboxes — it is NOT a browser API. This app is also deployed as a plain static
// site (GitHub Pages, via .github/workflows/deploy.yml), where `window.storage` is
// simply undefined. Without this shim, every save/load below silently failed on the
// real deployed site: Save Character always showed "Could not save", the saved list
// stayed empty forever, and preferences never persisted across a reload.
// Feature-detect and fall back to a same-shaped localStorage-backed implementation.
const storage = (function(){
  if (typeof window !== 'undefined' && window.storage &&
      typeof window.storage.get === 'function' && typeof window.storage.set === 'function' &&
      typeof window.storage.list === 'function' && typeof window.storage.delete === 'function'){
    return window.storage;
  }
  const PREFIX = 'cc_storage:';
  // localStorage itself can throw (private browsing in some browsers, storage
  // disabled) — fall back to an in-memory Map so the app still runs, it just
  // won't persist across reloads.
  let backend;
  try {
    const probeKey = '__cc_storage_probe__';
    window.localStorage.setItem(probeKey, '1');
    window.localStorage.removeItem(probeKey);
    backend = window.localStorage;
  } catch(e){
    const mem = new Map();
    backend = {
      getItem: k => mem.has(k) ? mem.get(k) : null,
      setItem: (k,v) => mem.set(k,v),
      removeItem: k => mem.delete(k),
      get length(){ return mem.size; },
      key: i => [...mem.keys()][i],
    };
  }
  return {
    async get(key){
      const v = backend.getItem(PREFIX + key);
      return v === null ? null : { value: v };
    },
    async set(key, value){ backend.setItem(PREFIX + key, value); },
    async delete(key){ backend.removeItem(PREFIX + key); },
    async list(prefix){
      const keys = [];
      for (let i = 0; i < backend.length; i++){
        const k = backend.key(i);
        if (k && k.startsWith(PREFIX + prefix)) keys.push(k.slice(PREFIX.length));
      }
      return { keys };
    },
  };
})();

async function saveCharacter(btnEl){
  if(!Object.keys(state).length){ alert("Generate a character first."); return; }
  const name = charMeta.name || prompt("Name this character voice:");
  if(!name) return;
  const btn = btnEl || null;
  const oldLabel = btn ? btn.textContent : null;
  if (btn){ btn.textContent = "Saving…"; btn.disabled = true; }
  try {
    await storage.set('character:'+name, JSON.stringify({state, charMeta, pressureState, pinnedTargets, charVariants}));
    await loadSavedList();
  } catch(e){ console.error(e); alert("Could not save — try again."); }
  finally { if (btn){ btn.textContent = oldLabel; btn.disabled = false; } }
}
async function deleteSavedCharacter(name){
  if (!confirm(`Delete the saved character "${name}"? This can't be undone.`)) return;
  try { await storage.delete('character:'+name); await loadSavedList(); }
  catch(e){ console.error(e); alert("Could not delete — try again."); }
}
async function loadSavedList(){
  const listEl = document.getElementById('savedList');
  try {
    const res = await storage.list('character:');
    if(!res || !res.keys || !res.keys.length){ listEl.textContent = ""; return; }
    listEl.innerHTML = "Saved: ";
    res.keys.forEach(k=>{
      const name = k.replace('character:','');
      // BUG FIX: there was previously no way to remove a saved character — the list
      // only ever grew. Wrap the name and a small × so cleanup doesn't require
      // going around the storage API by hand.
      const wrap = document.createElement('span');
      wrap.style.display = 'inline-flex'; wrap.style.alignItems = 'center'; wrap.style.gap = '2px';
      const span = document.createElement('span');
      span.textContent = name;
      span.style.cursor = 'pointer';
      span.onclick = async ()=>{
        try {
          const r = await storage.get(k);
          const parsed = JSON.parse(r.value);
          state = parsed.state; charMeta = parsed.charMeta || {name, age:"", context:"", archetypeLabel:"Loaded"};
          pressureState = parsed.pressureState || null;
          pinnedTargets = parsed.pinnedTargets || {};
          charVariants = parsed.charVariants || {};
          document.getElementById('charName').value = charMeta.name || "";
          document.getElementById('charAge').value = charMeta.age || "";
          document.getElementById('charContext').value = charMeta.context || "";
          document.getElementById('archetypeTag').textContent = "Loaded: "+name;
          document.getElementById('pressureSheet').style.display = pressureState ? "block" : "none";
          diffLog = {}; rerollExclusions = {}; whyOpen = {};
          renderSheet(); checkConflicts();
        } catch(e){ console.error(e); }
      };
      const del = document.createElement('button');
      del.textContent = '×'; del.title = 'Delete this saved character';
      del.style.cssText = 'border:none;background:none;color:var(--bubblegum);font-weight:800;cursor:pointer;padding:0 6px;font-size:.9rem;';
      del.onclick = (ev)=>{ ev.stopPropagation(); deleteSavedCharacter(name); };
      wrap.appendChild(span); wrap.appendChild(del);
      listEl.appendChild(wrap);
    });
  } catch(e){ /* none saved yet */ }
}

// ================= CAST COMPARISON =================
let castStates = [];
function randomAxisLevel(){ return (Math.random()*4) - 2; }

function generateCast(){
  const count = intVal('castCount', 3);
  const rarityPref = "balanced";
  castStates = [];
  for (let i=0;i<count;i++){
    const verbLevel = randomAxisLevel();
    const regLevel = randomAxisLevel();
    const compLevel = randomAxisLevel();
    const personalityOverrides = {};
    PERSONALITY_AXES.forEach(axis=>{ personalityOverrides[axis.id] = Math.round(randomAxisLevel()*50); });
    const st = buildCharacterState({verbLevel, regLevel, compLevel, mannerCount:3, rarityPref, vocabPref:null, personalityOverrides});
    castStates.push({state: st, meta: {name:"Character " + (i+1), age:"", context:"", archetypeLabel:"Cast member"}});
  }
  renderCast();
}
const CAST_COLORS = ["#4a6b8a","#c2578a","#5a9a6f","#b8860b","#8a6bbf","#c96f4a"];
function renderCast(){
  const grid = document.getElementById('castGrid');
  grid.innerHTML = "";
  // Cast overlay radar: every member's axis profile on one chart, so ensemble
  // gaps (an axis nobody covers) and pile-ups (everyone leaning the same way)
  // are visible at a glance instead of only via the text balance checker.
  const overlay = document.getElementById('castRadar');
  if (overlay){
    const profiles = castStates.map((c,i)=>({label:c.meta.name, color:CAST_COLORS[i%CAST_COLORS.length], prof:axisProfile(c.state)}))
                               .filter(p=>Object.keys(p.prof).length >= 2);
    if (profiles.length >= 2){
      let legend = profiles.map(p=>`<span style="display:inline-flex;align-items:center;gap:5px;margin-right:12px;font-size:.75rem;"><i style="width:10px;height:10px;border-radius:2px;background:${p.color};display:inline-block;"></i>${p.label}</span>`).join("");
      overlay.innerHTML = `<div class="tensionTitle" style="color:var(--dusk-blue);margin-bottom:4px;">Cast overlay — axis profiles</div>${radarSVG(profiles, 360)}<div style="margin-top:6px;">${legend}</div><div class="sub" style="margin:6px 0 0;">All members on one chart. Overlapping shapes = characters pulling the same directions; empty axes = ground nobody in this ensemble covers.</div>`;
      overlay.style.display = "block";
    } else overlay.style.display = "none";
  }
  castStates.forEach((c)=>{
    const card = document.createElement('div');
    card.className = "castCard";
    let inner = `<h3>${c.meta.name}</h3>`;
    const addAll = (ids)=>{ ids.forEach(id=>{ inner += traitCardHTML(id, c.state[id], false, false, sectionColor(titleForSlotId(id))); }); };
    addAll(Object.keys(c.state).filter(k=>k.startsWith("pers_")));
    addAll(Object.keys(c.state).filter(k=>k.startsWith("prof_")));
    addAll(["verbosity","register","grammar"].filter(id=>c.state[id]));
    addAll(Object.keys(c.state).filter(k=>k.startsWith("vocab")));
    addAll(Object.keys(c.state).filter(k=>k.startsWith("manner")));
    card.innerHTML = inner;
    grid.appendChild(card);
  });
}
function castToMarkdown(){
  const head = `# Character Cast\n\n_${castStates.length} characters_\n`;
  return head + castStates.map(c=>sheetToText(c.state, c.meta, null)).join("\n");
}
function copyCast(btnEl){
  copyText(castToMarkdown(), btnEl);
}
function downloadCast(){
  downloadText(castToMarkdown(), "character_cast.md");
}

function switchTab(which){
  document.getElementById('view-single').classList.toggle('active', which==='single');
  document.getElementById('view-cast').classList.toggle('active', which==='cast');
  document.getElementById('view-rel').classList.toggle('active', which==='rel');
  document.getElementById('tabSingleBtn').classList.toggle('active', which==='single');
  document.getElementById('tabCastBtn').classList.toggle('active', which==='cast');
  document.getElementById('tabRelBtn').classList.toggle('active', which==='rel');
  if (which==='rel') refreshRelSelectors();
}

// ---------- live slider readouts + affinity preview ----------
// PERF FIX: the affinity preview + deterministic profile prediction walk the full
// weight matrix and category lists; running that on EVERY input event made slider
// drags stutter. Numeric readouts stay instant; the heavy preview coalesces to one
// trailing run ~80ms after the drag pauses.
let _previewTimer = null;
function onSliderChange(){
  updateSliderReadouts();
  if (_previewTimer) clearTimeout(_previewTimer);
  _previewTimer = setTimeout(updateHeavyPreview, 80);
}
function updateSliderReadouts(){
  const vRaw = intVal('verbositySlider', 0);
  const rRaw = intVal('registerSlider', 0);
  const cRaw = intVal('composureSlider', 0);
  document.getElementById('verbosityVal').textContent = vRaw;
  document.getElementById('registerVal').textContent = rRaw;
  document.getElementById('composureVal').textContent = cRaw;
  PERSONALITY_AXES.forEach(axis=>{
    const el = document.getElementById('pers_'+axis.id);
    const out = document.getElementById('persVal_'+axis.id);
    if (el && out) out.textContent = el.value;
    // Show whether this axis actually made it into the last generated sheet. With
    // "N (random)" selected the tool silently drops axes; without this the slider
    // looks active but produces nothing, which reads as a bug.
    const field = el ? el.closest('.persField') : null;
    if (field){
      const trimmed = lastAxisTrimActive && lastAxesUsed && !lastAxesUsed.has(axis.id);
      field.classList.toggle('axisTrimmed', !!trimmed);
      if (trimmed){
        const raw = parseInt(el.value);
        field.title = Math.abs(raw) > 10
          ? `Not used in the last generation. "Personality axes" is set below ${PERSONALITY_AXES.length}, so only some axes are drawn. Axes you've moved off centre are picked first — this one lost a tie-break. Raise the axis count to include it every time.`
          : `Not used in the last generation. "Personality axes" is set below ${PERSONALITY_AXES.length}, and axes left at 0 are the first to be dropped. Move this slider off centre to prioritise it, or raise the axis count.`;
      } else if (lastAxesUsed && lastAxesUsed.has(axis.id)){
        field.title = "Included in the last generated sheet.";
      } else {
        field.title = "";
      }
    }
  });

}
function updateHeavyPreview(){
  const vRaw = intVal('verbositySlider', 0);
  const rRaw = intVal('registerSlider', 0);
  const cRaw = intVal('composureSlider', 0);
  const verbLevel = rawToLevel(vRaw), regLevel = rawToLevel(rRaw), compLevel = rawToLevel(cRaw);
  // BUG FIX: this called resolveProfileCategories(), which performs a *random weighted
  // draw*. It ran on every single input event, so the "Character Profile (auto)" preview
  // reshuffled on every pixel of slider travel and showed a different "likely" answer
  // each time — it looked broken and told you nothing. Use the deterministic
  // highest-weighted category instead: a genuine prediction, stable while you drag.
  let resolvedCats = {};
  try { resolvedCats = predictProfileCategories(); } catch(e){ /* UI not fully built yet */ }
  const gBoost = boostedGrammarCats(verbLevel, compLevel, regLevel, resolvedCats);
  const vBoost = boostedVocabCats(verbLevel, regLevel, resolvedCats);
  const mBoost = boostedMannerCats(compLevel, regLevel, resolvedCats);
  const boostVal = AFFINITY();

  function fmt(map, label){
    if (!map.size) return `<div><b>${label}:</b> no boosted categories at current settings</div>`;
    const parts = [...map.entries()].sort((a,b)=>b[1]-a[1]).map(([c,s])=>`${c} (×${(1+boostVal*s).toFixed(1)})`);
    return `<div><b>${label}:</b> ${parts.join(", ")}</div>`;
  }
  let profLine = "";
  try {
    const {chosen, conf} = predictProfileCategories(true);
    const parts = PROFILE_SECTIONS.filter(ps=>chosen[ps.id]).map(ps=>{
      const pct = Math.round((conf[ps.id]||0)*100);
      return `${ps.label} → most likely <b>${chosen[ps.id]}</b> <span style="opacity:.65">(~${pct}%)</span>`;
    });
    if (parts.length) profLine = `<div style="margin-top:6px; padding-top:6px; border-top:1px dashed var(--border);"><b>Character Profile (predicted):</b><br>${parts.join("<br>")}<div class="sub" style="margin:6px 0 0;">Deterministic prediction, not a draw — generation still rolls against these odds.</div></div>`;
  } catch(e){}
  document.getElementById('affinityPreview').innerHTML =
    fmt(gBoost,"Grammar") + fmt(vBoost,"Vocabulary") + fmt(mBoost,"Mannerisms") + profLine;
  updateRangeReadout();
}

// Live explanation of what the three voice sliders are currently targeting, in the
// same units the trait cards use. Without this the new continuous range engine is
// invisible: you'd feel the difference between 35 and 45 but never see why.
function updateRangeReadout(){
  const box = document.getElementById('rangeReadout');
  if (!box) return;
  const half = bandHalf();
  const rows = [
    ['Verbosity','verbositySlider'], ['Register','registerSlider'], ['Composure','composureSlider']
  ].map(([label,id])=>{
    const raw = Math.abs(intVal(id, 0));
    const t = targetFromMag(raw);
    const lo = Math.max(1, t - half).toFixed(2), hi = Math.min(5, t + half).toFixed(2);
    return `<div><b>${label}:</b> targets intensity <b>${t.toFixed(2)}</b> · accepts ${lo}–${hi}</div>`;
  });
  const pw = document.getElementById('profileWeight');
  if (pw){
    const t = targetFromMag(parseInt(pw.value)||0);
    rows.push(`<div><b>Profile weight:</b> targets intensity <b>${t.toFixed(2)}</b></div>`);
  }
  rows.push(`<div class="sub" style="margin:6px 0 0;">Window half-width ${half.toFixed(2)} — narrower means the sliders dictate more tightly and results vary less.</div>`);
  box.innerHTML = rows.join("");
}

function buildPersonalitySliders(){
  const grid = document.getElementById('personalitySlidersGrid');
  grid.innerHTML = "";
  PERSONALITY_AXES.forEach(axis=>{
    const div = document.createElement('div');
    div.className = "field persField";
    div.innerHTML = `
      <label>${axis.label}</label>
      <input type="range" id="pers_${axis.id}" min="-100" max="100" value="0" step="1" oninput="onSliderChange()">
      <div class="scaleLabels"><span>${axis.neg.split('—')[1] ? axis.neg.split('—')[1].trim() : 'Low'}</span><span>${axis.pos.split('—')[1] ? axis.pos.split('—')[1].trim() : 'High'}</span></div>
      <div class="sliderVal" id="persVal_${axis.id}">0</div>
    `;
    grid.appendChild(div);
  });
}
function togglePersonalityPanel(){
  const enabled = document.getElementById('personalityToggle').checked;
  document.getElementById('personalitySlidersGrid').classList.toggle('disabled', !enabled);
}

function toggleExamples(){
  const show = document.getElementById('examplesToggle').checked;
  document.body.classList.toggle('hide-examples', !show);
}

function resetAllToDefaults(){
  // BUG FIX: this cleared persisted preferences and per-slot UI state BEFORE asking
  // for confirmation, so cancelling the dialog still silently wiped your saved
  // settings. Confirm first, mutate second.
  if (!confirm("Reset every slider, toggle, and field back to defaults? Your generated character stays until you generate again.")) return;
  try { storage.delete(PREF_KEY); } catch(e){}
  rerollExclusions = {}; whyOpen = {}; lastDepthUntouched = []; pinnedTargets = {};
  lastAxesUsed = null; lastAxisTrimActive = false;
  document.getElementById('verbositySlider').value = 0;
  document.getElementById('registerSlider').value = 0;
  document.getElementById('composureSlider').value = 0;
  PERSONALITY_AXES.forEach(a=>{ const el = document.getElementById('pers_'+a.id); if (el) el.value = 0; });
  PROFILE_SECTIONS.forEach(ps=>{
    const tog = document.getElementById('sec_'+ps.id); if (tog) tog.checked = true;
    const sel = document.getElementById('type_'+ps.id); if (sel) sel.value = "";
  });
  document.getElementById('charName').value = "";
  document.getElementById('charAge').value = "";
  document.getElementById('charContext').value = "";
  document.getElementById('archetypeSelect').value = "";
  document.getElementById('mannerCount').value = "3";
  document.getElementById('vocabCount').value = "2";
  document.getElementById('rarityPref').value = "balanced";
  document.getElementById('personalityCount').value = "13";
  document.getElementById('profileDepth').value = "1";
  document.getElementById('affinityBoost').value = "2.5";
  const rf = document.getElementById('rangeFocus'); if (rf) rf.value = "0.62";
  const pw = document.getElementById('profileWeight'); if (pw) pw.value = "55";
  document.getElementById('stressToggle').checked = false;
  document.getElementById('personalityToggle').checked = true;
  document.getElementById('examplesToggle').checked = true;
  const depthFirst = document.getElementById('depthFirstToggle'); if (depthFirst) depthFirst.checked = false;
  const seedFilter = document.getElementById('seedTraitFilter'); if (seedFilter) seedFilter.value = "";
  const seedSel = document.getElementById('seedTraitSelect'); if (seedSel) seedSel.value = "";
  document.body.classList.remove('hide-examples');
  togglePersonalityPanel();
  onSliderChange();
}

function randomRawSlider(){
  // biased toward the extremes a bit so randomized characters read as distinctive, not muddy-neutral
  const r = Math.random();
  let v;
  if (r < 0.6) { v = (Math.random()*2-1) * 100; }           // 60%: anywhere in range
  else { v = (Math.random() < 0.5 ? -1 : 1) * (60 + Math.random()*40); } // 40%: pushed toward an extreme
  return Math.round(clamp(v, -100, 100));
}

function randomizeSliders(scope){
  if (scope === 'voice' || scope === 'all'){
    document.getElementById('verbositySlider').value = randomRawSlider();
    document.getElementById('registerSlider').value = randomRawSlider();
    document.getElementById('composureSlider').value = randomRawSlider();
  }
  if (scope === 'personality' || scope === 'all'){
    PERSONALITY_AXES.forEach(axis=>{
      const el = document.getElementById('pers_'+axis.id);
      if (el) el.value = randomRawSlider();
    });
  }
  onSliderChange();
}


// ================= CUSTOM ARCHETYPES =================
async function saveCustomArchetype(btnEl){
  const name = document.getElementById('customArchName').value.trim();
  if(!name){ alert("Give the archetype a name first."); return; }
  const btn = btnEl || null;
  const oldLabel = btn ? btn.textContent : null;
  if (btn){ btn.textContent = "Saving…"; btn.disabled = true; }
  const pers = {};
  PERSONALITY_AXES.forEach(axis=>{
    const el = document.getElementById('pers_'+axis.id);
    if (el) pers[axis.id] = parseInt(el.value);
  });
  const arch = {
    label: name,
    verbosity: rawToLevel(intVal('verbositySlider', 0)),
    register: rawToLevel(intVal('registerSlider', 0)),
    composure: rawToLevel(intVal('composureSlider', 0)),
    vocabPref: null,
    pers
  };
  try {
    await storage.set('archetype:'+name, JSON.stringify(arch));
    CUSTOM_ARCHETYPES['custom_'+name] = arch;
    await loadCustomArchetypes();
    document.getElementById('customArchName').value = "";
  } catch(e){ console.error(e); alert("Could not save archetype."); }
  finally { if (btn){ btn.textContent = oldLabel; btn.disabled = false; } }
}

async function deleteCustomArchetype(){
  const sel = document.getElementById('archetypeSelect');
  const key = sel.value;
  if (!key.startsWith('custom_')){ alert("Select one of your custom archetypes in the dropdown first."); return; }
  const name = key.replace('custom_','');
  if (!confirm(`Delete the archetype "${name}"? This can't be undone.`)) return;
  try {
    await storage.delete('archetype:'+name);
    delete CUSTOM_ARCHETYPES[key];
    await loadCustomArchetypes();
  } catch(e){ console.error(e); alert("Could not delete — try again."); }
}

async function loadCustomArchetypes(){
  try {
    const res = await storage.list('archetype:');
    CUSTOM_ARCHETYPES = {};
    if (res && res.keys){
      for (const k of res.keys){
        try {
          const r = await storage.get(k);
          const arch = JSON.parse(r.value);
          CUSTOM_ARCHETYPES['custom_'+arch.label] = arch;
        } catch(e){}
      }
    }
  } catch(e){}
  // rebuild dropdown
  const sel = document.getElementById('archetypeSelect');
  const current = sel.value;
  [...sel.querySelectorAll('option')].forEach(o=>{ if(o.value.startsWith('custom_')) o.remove(); });
  Object.entries(CUSTOM_ARCHETYPES).forEach(([key,arch])=>{
    const opt = document.createElement('option');
    opt.value = key; opt.textContent = arch.label + " (custom)";
    sel.appendChild(opt);
  });
  if ([...sel.options].some(o=>o.value===current)) sel.value = current;
  const list = document.getElementById('customArchList');
  const names = Object.values(CUSTOM_ARCHETYPES).map(a=>a.label);
  list.textContent = names.length ? "Saved archetypes: " + names.join(", ") : "";
}

// ================= RELATIONSHIP GENERATOR =================
function refreshRelSelectors(){
  const a = document.getElementById('relA'), b = document.getElementById('relB');
  const opts = [];
  if (Object.keys(state).length) opts.push({key:"__single__", label:(charMeta.name||"Current character")});
  castStates.forEach((c,i)=> opts.push({key:"cast_"+i, label:c.meta.name}));
  [a,b].forEach((sel,idx)=>{
    const prev = sel.value;
    sel.innerHTML = "";
    opts.forEach(o=>{
      const el = document.createElement('option');
      el.value = o.key; el.textContent = o.label; sel.appendChild(el);
    });
    if ([...sel.options].some(o=>o.value===prev)) sel.value = prev;
    else if (opts.length > 1) sel.value = opts[Math.min(idx, opts.length-1)].key;
  });
}
function getCharByKey(key){
  if (key === "__single__") return {state, meta: charMeta};
  const i = parseInt(key.replace("cast_",""));
  return castStates[i];
}
function axisProfile(st){
  // Aggregate polarity across a character's Personality AND Profile-section traits —
  // previously this only read pers_ slots, so Values/Attachment/Role/etc (arguably the
  // more predictive data for how two characters clash) were invisible to Relationship
  // and Ensemble analysis. Voice traits carry pol too but are deliberately excluded here:
  // this profile is about who the character IS, not how they happen to phrase things.
  const prof = {};
  Object.keys(st).filter(k=>k.startsWith("pers_") || k.startsWith("prof_")).forEach(id=>{
    // BUG FIX: slots can legitimately hold a null trait (exhausted pool, disabled
    // section on a loaded save); dereferencing .trait.pol here crashed the whole
    // Relationship and Ensemble tools for that character.
    const t = st[id] && st[id].trait;
    if (!t || !t.pol) return;
    Object.entries(t.pol).forEach(([ax,v])=>{
      if (!AXIS_LABELS[ax]) return;
      prof[ax] = (prof[ax]||0) + v;
    });
  });
  return prof;
}
// Category-pair interpretive notes for the two-character Relationship view — the same
// "resolved category X meets resolved category Y" pattern TENSION_RULES/SECOND_ORDER_RULES
// already use for single-character tension detection, ported here because axis-sum math
// alone (axisProfile) can't see Values/Role/Attachment/Stress/Humor/Vices identity, which
// is often the more narratively decisive thing two characters clash or align on.
// Order-independent: each rule matches regardless of which character is A and which is B.
const RELATIONSHIP_CATEGORY_RULES = [
  {a:{sec:"role",cat:"Leader"}, b:{sec:"role",cat:"Leader"},
   note:"Two leaders in the same room. Either they split turf cleanly, or every shared decision becomes a quiet contest over who actually has the floor."},
  {a:{sec:"role",cat:"Leader"}, b:{sec:"role",cat:"Outsider"},
   note:"A leader and an outsider. The leader keeps trying to fold them in; the outsider reads every attempt as either an audition or a trap."},
  {a:{sec:"role",cat:"Instigator"}, b:{sec:"role",cat:"Peacemaker"},
   note:"An instigator paired with a peacemaker: one lights the fire, the other keeps putting it out. Neither can fully stop, or the relationship loses its function."},
  {a:{sec:"role",cat:"Caretaker"}, b:{sec:"role",cat:"Caretaker"},
   note:"Two caretakers. Warm, but nobody in the pairing is actually being taken care of — watch for who quietly runs out first."},
  {a:{sec:"role",cat:"Skeptic"}, b:{sec:"values",cat:"Idealistic & Visionary"},
   note:"A skeptic across from a true believer. The skeptic's questions read as sabotage to the idealist; the idealist's certainty reads as naivety to the skeptic."},
  {a:{sec:"values",cat:"Rigid & Principled"}, b:{sec:"values",cat:"Self-Interested"},
   note:"A fixed code across from someone who bends for advantage. Every shared decision becomes a referendum on which of them the situation actually rewards."},
  {a:{sec:"values",cat:"Loyalty-Bound"}, b:{sec:"values",cat:"Self-Interested"},
   note:"One measures every choice by who it's owed to; the other by what it gets them. They can cooperate a long time before either notices they're keeping score differently."},
  {a:{sec:"attachment",cat:"Anxious"}, b:{sec:"attachment",cat:"Avoidant"},
   note:"The classic pursue-withdraw pair: the more one reaches, the more the other retreats — which only confirms the first one's fear and accelerates the reach."},
  {a:{sec:"attachment",cat:"Secure"}, b:{sec:"attachment",cat:"Secure"},
   note:"Two securely attached people. Unusually low-drama by this tool's standards — the tension in this pairing has to come from outside the relationship, not inside it."},
  {a:{sec:"stress",cat:"Fight (attack the threat)"}, b:{sec:"stress",cat:"Fight (attack the threat)"},
   note:"Both come out swinging under pressure. Fine as allies against a shared threat; explosive the moment the threat is each other."},
  {a:{sec:"stress",cat:"Freeze (shut down)"}, b:{sec:"stress",cat:"Fawn (appease the threat)"},
   note:"One shuts down, the other starts placating — and the placating reads to the frozen one as more pressure, which shuts them down further."},
  {a:{sec:"humor",cat:"Cruel & Barbed"}, b:{sec:"humor",cat:"Warm & Playful"},
   note:"One's jokes draw blood, the other's don't. The warm one keeps extending the benefit of the doubt long after it's stopped being funny to them."},
  {a:{sec:"humor",cat:"Dry & Deadpan"}, b:{sec:"humor",cat:"Dry & Deadpan"},
   note:"Two deadpan deliveries. Outsiders often can't tell either of them is joking at all; each other, they read instantly."},
  {a:{sec:"vices",cat:"Restraint & Discipline"}, b:{sec:"vices",cat:"Risk & Escape"},
   note:"One's whole structure is control; the other's is release. They either regulate each other or each quietly resents what the other represents."},
];
function categoryPairNotesFor(stA, stB){
  const catOf = (st,id) => (st["prof_"+id+"_0"] ? st["prof_"+id+"_0"].trait.category : null);
  const notes = [];
  RELATIONSHIP_CATEGORY_RULES.forEach(r=>{
    const forward = catOf(stA, r.a.sec) === r.a.cat && catOf(stB, r.b.sec) === r.b.cat;
    const reverse = catOf(stB, r.a.sec) === r.a.cat && catOf(stA, r.b.sec) === r.b.cat;
    if (forward || reverse) notes.push(r.note);
  });
  return [...new Set(notes)];
}
function analyseRelationship(){
  const ka = document.getElementById('relA').value, kb = document.getElementById('relB').value;
  const A = getCharByKey(ka), B = getCharByKey(kb);
  if (!A || !B){ alert("Generate a character or cast first."); return; }
  if (ka === kb){ alert("Pick two different characters."); return; }

  const pa = axisProfile(A.state), pb = axisProfile(B.state);
  const clashes = [], alignments = [], notes = [];
  const allAxes = new Set([...Object.keys(pa), ...Object.keys(pb)]);
  allAxes.forEach(ax=>{
    const va = pa[ax]||0, vb = pb[ax]||0;
    if (va === 0 || vb === 0) return;
    const label = AXIS_LABELS[ax];
    if (va > 0 !== vb > 0){
      clashes.push({ax, label, va, vb, mag: Math.abs(va)+Math.abs(vb)});
    } else {
      alignments.push({ax, label, va, vb, mag: Math.abs(va)+Math.abs(vb)});
    }
  });
  clashes.sort((x,y)=>y.mag-x.mag);
  alignments.sort((x,y)=>y.mag-x.mag);

  // Interpretive notes for specific high-signal axis pairings
  const bothHigh = ax => (pa[ax]||0) > 0 && (pb[ax]||0) > 0;
  const bothLow = ax => (pa[ax]||0) < 0 && (pb[ax]||0) < 0;
  if (bothHigh('rebel')) notes.push("Both push against authority — expect either fast alliance or a contest over who leads the rebellion.");
  if (bothHigh('asrt')) notes.push("Two people used to running the room. Every shared decision becomes a negotiation.");
  if (bothLow('asrt')) notes.push("Neither will make the first move. Conversations stall in mutual deference.");
  if ((pa['hon']||0) * (pb['hon']||0) < 0) notes.push("One deals straight, the other doesn't. This is the fault line the relationship eventually breaks along.");
  if (bothLow('warm')) notes.push("Two cold fronts. Mutual respect is possible; intimacy isn't, without something forcing it.");
  if ((pa['warm']||0) > 0 && (pb['warm']||0) < 0) notes.push("One keeps reaching, the other keeps stepping back. Reads as pursuit and retreat.");
  if ((pa['emo']||0) * (pb['emo']||0) < 0) notes.push("One processes out loud, the other shuts down. Each reads the other's coping as a personal rejection.");
  if (bothHigh('ego')) notes.push("Two secure egos — surprisingly stable, provided their goals don't overlap.");
  if ((pa['disc']||0) * (pb['disc']||0) < 0) notes.push("One plans, the other improvises. Productive in a crisis, corrosive over a long campaign.");
  if ((pa['pos']||0) * (pb['pos']||0) < 0) notes.push("Optimist and pessimist. Each thinks the other is being wilfully unhelpful.");
  if ((pa['act']||0) * (pb['act']||0) < 0) notes.push("Mismatched tempo — one is always waiting, the other always being rushed.");
  if (bothHigh('intel')) notes.push("Both sharp. Conversation runs fast and competitive; neither explains themselves.");
  if ((pa['mood']||0) < 0 && (pb['mood']||0) < 0) notes.push("Both currently in a bad place. Whatever happens between them now isn't representative.");
  // Manners ('man') previously had zero interpretive notes here despite being one of
  // the more dramatically obvious clashes available (Ritual-observant vs. Totally
  // uncouth) — every other personality axis had at least one.
  if (bothHigh('man')) notes.push("Both scrupulously mannered. Pleasant on the surface — but a real breach of etiquette between them will land as a genuine violation, not a quirk to shrug off.");
  if (bothLow('man')) notes.push("Neither minds their manners. Blunt and efficient with each other; occasionally, accidentally cruel to anyone who expected softening.");
  if ((pa['man']||0) * (pb['man']||0) < 0) notes.push("One minds their manners, the other doesn't bother. Every interaction becomes a small, usually unspoken referendum on how much decorum the room requires.");

  notes.push(...categoryPairNotesFor(A.state, B.state));

  let heat = clashes.reduce((s,c)=>s+c.mag,0);
  let bond = alignments.reduce((s,c)=>s+c.mag,0);
  let verdict;
  if (heat > bond*1.8) verdict = "Volatile — this pairing generates friction faster than trust.";
  else if (bond > heat*1.8) verdict = "Easy — they slot together with little resistance (possibly too little for drama).";
  else verdict = "Mixed — real common ground with real fault lines. The most dramatically useful kind.";

  const sheet = document.getElementById('relSheet');
  sheet.classList.add('show');
  document.getElementById('relTitle').textContent = (A.meta.name||"A") + "  ×  " + (B.meta.name||"B");
  let h = `<div class="charMeta">${verdict}</div>`;
  if (clashes.length){
    h += `<div class="axisGroup"><div class="axisTitle">Friction points</div>`;
    clashes.slice(0,6).forEach(c=>{
      h += `<div class="traitCard"><div class="traitMain"><div class="traitName">${c.label}</div>
        <div class="traitDesc">${A.meta.name||'A'} leans ${c.va>0?'high':'low'}; ${B.meta.name||'B'} leans ${c.vb>0?'high':'low'}.</div></div></div>`;
    });
    h += `</div>`;
  }
  if (alignments.length){
    h += `<div class="axisGroup"><div class="axisTitle">Common ground</div>`;
    alignments.slice(0,6).forEach(c=>{
      h += `<div class="traitCard"><div class="traitMain"><div class="traitName">${c.label}</div>
        <div class="traitDesc">Both lean ${c.va>0?'high':'low'} here.</div></div></div>`;
    });
    h += `</div>`;
  }
  if (notes.length){
    h += `<div class="axisGroup"><div class="axisTitle">What this looks like in a scene</div>`;
    notes.forEach(n=>{ h += `<div class="traitCard"><div class="traitMain"><div class="traitDesc">${n}</div></div></div>`; });
    h += `</div>`;
  }
  if (!clashes.length && !alignments.length && !notes.length){
    h += `<div class="charMeta">Not enough personality signal to compare — generate both characters with the personality profile enabled.</div>`;
  }
  document.getElementById('relBody').innerHTML = h;
}
function copyRelationship(btnEl){
  const t = document.getElementById('relTitle').textContent + "\n\n" + document.getElementById('relBody').innerText;
  navigator.clipboard.writeText(t).then(()=>{
    if (!btnEl) return;
    const old = btnEl.textContent;
    btnEl.textContent = "Copied!"; setTimeout(()=>btnEl.textContent=old, 1200);
  });
}


// ================= PERSONALITY -> VOICE SUGGESTION =================
// Maps aggregate personality posture onto sensible voice slider positions.
// Deliberately overridable: it sets the sliders, it doesn't lock them.
function suggestVoiceFromPersonality(){
  const P = id => { const el = document.getElementById('pers_'+id); return el ? parseInt(el.value) : 0; };
  const frnd=P('friendliness'), hon=P('honesty'), asrt=P('assertiveness'), conf=P('confidence'),
        agr=P('agreeableness'), man=P('manners'), disc=P('discipline'), reb=P('rebelliousness'),
        emo=P('emotionalcapacity'), intel=P('intelligence'), pos=P('positivity'), act=P('activeness');

  // Verbosity: talkativeness rises with friendliness, assertiveness, energy, emotional openness;
  // falls with guardedness, deception, and passivity.
  let verbosity = 0.30*frnd + 0.25*asrt + 0.20*act + 0.25*emo - 0.20*Math.max(0,-hon) - 0.15*Math.max(0,-conf);
  // Register: formality rises with manners, intelligence, discipline; falls with rebelliousness.
  let register  = 0.45*man + 0.30*intel + 0.15*disc - 0.30*reb;
  // Composure: volatility rises with impulsiveness, emotional openness, bad mood, low confidence, contrarianism.
  let composure = 0.35*Math.max(0,-disc) + 0.30*emo + 0.20*Math.max(0,-conf) + 0.15*Math.max(0,-agr) - 0.20*Math.max(0,disc) - 0.15*Math.max(0,pos);

  const setS = (id,v)=>{ document.getElementById(id).value = Math.round(clamp(v,-100,100)); };
  setS('verbositySlider', verbosity);
  setS('registerSlider', register);
  setS('composureSlider', composure);
  onSliderChange();

  const box = document.getElementById('suggestNote');
  if (box){
    box.style.display = 'block';
    box.textContent = `Suggested from personality — Verbosity ${Math.round(clamp(verbosity,-100,100))}, Register ${Math.round(clamp(register,-100,100))}, Composure ${Math.round(clamp(composure,-100,100))}. Adjust freely; nothing is locked.`;
  }
}

// ================= FOIL FINDER =================
// Builds a character deliberately opposed on 2-3 personality axes and aligned on 1-2.
// Canonical oppositions for the multi-way Profile sections (there's no single numeric
// spectrum for a 4-6 way category the way Personality axes have one, so these are
// hand-picked "most narratively opposed" pairs rather than derived from anything).
const OPPOSED_CATEGORIES = {
  role: {"Leader":"Outsider","Outsider":"Leader","Peacemaker":"Instigator","Instigator":"Peacemaker","Caretaker":"Skeptic","Skeptic":"Caretaker"},
  values: {"Rigid & Principled":"Self-Interested","Self-Interested":"Rigid & Principled","Pragmatic & Flexible":"Loyalty-Bound","Loyalty-Bound":"Pragmatic & Flexible"},
  attachment: {"Secure":"Disorganized","Disorganized":"Secure","Anxious":"Avoidant","Avoidant":"Anxious"},
  stress: {"Fight (attack the threat)":"Flight (remove yourself)","Flight (remove yourself)":"Fight (attack the threat)","Freeze (shut down)":"Fawn (appease the threat)","Fawn (appease the threat)":"Freeze (shut down)"},
  humor: {"Warm & Playful":"Cruel & Barbed","Cruel & Barbed":"Warm & Playful","Dry & Deadpan":"Absurd & Chaotic","Absurd & Chaotic":"Dry & Deadpan"},
  vices: {"Restraint & Discipline":"Risk & Escape","Risk & Escape":"Restraint & Discipline","Avoidance & Procrastination":"Restraint & Discipline"},
};
// New sub-groups get one-way opposition entries (asymmetric is fine — lookup is always
// keyed off the SOURCE character's actual category, never requires the reverse to match).
OPPOSED_CATEGORIES.role["Connector"] = "Outsider";
OPPOSED_CATEGORIES.values["Idealistic & Visionary"] = "Self-Interested";
OPPOSED_CATEGORIES.humor["Intellectual & Wordplay"] = "Humorless & Absent";
function generateFoil(){
  if (!Object.keys(state).length){ alert("Generate a character first — the foil is built against them."); return; }
  const src = {};
  PERSONALITY_AXES.forEach(a=>{ const el=document.getElementById('pers_'+a.id); src[a.id]= el?parseInt(el.value):0; });

  // Prefer opposing axes where the source character actually has a strong position.
  const ranked = PERSONALITY_AXES.map(a=>({axis:a, mag:Math.abs(src[a.id])})).sort((x,y)=>y.mag-x.mag);
  const strong = ranked.filter(r=>r.mag>=25);
  const pool = strong.length>=3 ? strong : ranked;
  const shuffle = arr => arr.map(a=>[Math.random(),a]).sort((x,y)=>x[0]-y[0]).map(x=>x[1]);

  const opposeCount = 2 + (Math.random()<0.5?1:0); // 2 or 3
  const opposed = shuffle(pool.slice(0, Math.max(opposeCount+2, 4))).slice(0, opposeCount);
  const opposedIds = new Set(opposed.map(o=>o.axis.id));
  const alignCandidates = shuffle(PERSONALITY_AXES.filter(a=>!opposedIds.has(a.id)));
  const aligned = alignCandidates.slice(0, 1 + (Math.random()<0.5?1:0)); // 1 or 2

  const overrides = {};
  PERSONALITY_AXES.forEach(a=>{
    if (opposedIds.has(a.id)){
      const v = src[a.id];
      overrides[a.id] = Math.round(clamp((Math.abs(v) < 25 ? 55 : Math.abs(v)) * (v >= 0 ? -1 : 1), -100, 100));
    } else if (aligned.some(x=>x.id===a.id)){
      overrides[a.id] = Math.round(clamp(src[a.id] + (Math.random()*20-10), -100, 100));
    } else {
      overrides[a.id] = Math.round((Math.random()*2-1)*70);
    }
  });

  // Same opposition idea, applied to whichever Profile sections the source character
  // actually has a resolved category for. This is usually more narratively decisive
  // than opposed personality sliders alone — two characters with opposite Values or
  // Attachment styles clash in ways that don't show up as a personality-axis mismatch.
  const profSectionsWithSrc = ["values","attachment","role","stress","humor","vices"]
    .filter(id => state["prof_"+id+"_0"] && OPPOSED_CATEGORIES[id]);
  const profOpposeCount = Math.min(profSectionsWithSrc.length, 1 + (Math.random()<0.5?1:0)); // 1 or 2
  const profOpposed = shuffle(profSectionsWithSrc).slice(0, profOpposeCount);
  const forcedProfileCats = {};
  const profOpposedNames = [];
  profOpposed.forEach(id=>{
    const srcCat = state["prof_"+id+"_0"].trait.category;
    const oppCat = OPPOSED_CATEGORIES[id][srcCat];
    if (oppCat){
      forcedProfileCats[id] = oppCat;
      const ps = PROFILE_SECTIONS.find(p=>p.id===id);
      profOpposedNames.push(`${ps.label} (${srcCat} vs ${oppCat})`);
    }
  });

  const rarityPref = document.getElementById('rarityPref').value;
  const mannerCount = intVal('mannerCount', 3);
  const vocabCount = intVal('vocabCount', 2);
  // Verbosity and register invert by default — a foil that talks and phrases things
  // differently is the whole point. Composure stays aligned by default: it reads less
  // as "who they are" and more as "how bad the current scene is," so two characters
  // sharing a composure level plausibly share a scene without the foil relationship
  // requiring it. The "should also clash under pressure" checkbox opts into inverting
  // it too, for foils that need to fall apart differently as well.
  const composureToggleEl = document.getElementById('foilOpposeComposure');
  const opposeComposure = composureToggleEl ? composureToggleEl.checked : false;
  const composureRaw = rawToLevel(intVal('composureSlider', 0));
  const foilState = buildCharacterState({
    verbLevel: -rawToLevel(intVal('verbositySlider', 0)),
    regLevel:  -rawToLevel(intVal('registerSlider', 0)),
    compLevel: opposeComposure ? -composureRaw : composureRaw,
    mannerCount, rarityPref, vocabPref:null, personalityOverrides: overrides, vocabCount, forcedProfileCats
  });

  // The whole point of a foil is contrast — without the source character also on the
  // Cast tab, the "Opposed on... Shared ground on..." rationale below refers to a
  // character the user can't actually see next to it. Add the current character
  // alongside the foil (guarding against a duplicate name already in the cast).
  const srcName = charMeta.name || "Current character";
  castStates = castStates.filter(c=>c.meta.name !== "Foil" && c.meta.name !== srcName);
  castStates.push({state: {...state}, meta:{name: srcName, age: charMeta.age||"", context: charMeta.context||"", archetypeLabel: charMeta.archetypeLabel||"Source"}});
  castStates.push({state: foilState, meta:{name:"Foil", age:"", context:"Built against " + srcName, archetypeLabel:"Foil"}});
  renderCast();
  switchTab('cast');

  const opposedNames = opposed.map(o=>o.axis.label).join(", ");
  const alignedNames = aligned.map(a=>a.label).join(", ");
  const grid = document.getElementById('castGrid');
  const note = document.createElement('div');
  note.className = "castCard";
  note.innerHTML = `<h3>Foil rationale</h3>
    <div class="traitDesc"><b>Opposed on (personality):</b> ${opposedNames}</div>
    ${profOpposedNames.length ? `<div class="traitDesc" style="margin-top:6px;"><b>Opposed on (profile):</b> ${profOpposedNames.join(", ")}</div>` : ``}
    <div class="traitDesc" style="margin-top:6px;"><b>Shared ground on:</b> ${alignedNames||"—"}</div>
    <div class="traitDesc" style="margin-top:6px;">Opposition on a few axes creates friction; shared ground on one or two keeps them plausibly in the same room. Check the Relationships tab for the full read.</div>`;
  grid.insertBefore(note, grid.firstChild);
}

// ================= ENSEMBLE BALANCE CHECK =================
function checkEnsembleBalance(){
  if (castStates.length < 3){ alert("Generate a cast of at least 3 to check balance."); return; }
  const axisVals = {};
  PERSONALITY_AXES.forEach(a=> axisVals[a.id] = []);

  castStates.forEach(c=>{
    PERSONALITY_AXES.forEach(a=>{
      const slot = c.state["pers_"+a.id];
      if (!slot || !slot.trait) return;
      // Situational/mid-category picks (axis.mid) are a deliberate third outcome the
      // generator supports, not a quiet "low" — counting them as -1 falsely inflated
      // apparent clustering toward the negative pole, or diluted real one-sided
      // clustering with mis-tagged neutrals. Exclude them from the posture count.
      if (slot.neutral || slot.trait.category === a.mid) return;
      // derive a -1/+1 posture from which pole the chosen trait came from
      const isPos = slot.trait.category === a.pos;
      axisVals[a.id].push(isPos ? 1 : -1);
    });
  });

  const clustered = [], spread = [];
  Object.entries(axisVals).forEach(([id, vals])=>{
    if (vals.length < 3) return;
    const axis = PERSONALITY_AXES.find(a=>a.id===id);
    const sum = vals.reduce((a,b)=>a+b,0);
    const ratio = Math.abs(sum)/vals.length;
    if (ratio >= 0.8) clustered.push({axis, dir: sum>0?'high':'low', ratio});
    else if (ratio <= 0.34) spread.push({axis});
  });
  clustered.sort((a,b)=>b.ratio-a.ratio);

  // Same clustering check for the multi-way Profile sections (Role, Values, Stress, etc.) —
  // a cast can look varied on personality axes and still have everyone land on the same
  // Social Role or Stress Response, which personality clustering alone wouldn't catch.
  const profClustered = [];
  PROFILE_SECTIONS.filter(ps=>!ps.drawAll).forEach(ps=>{
    const picks = castStates.map(c=>{
      const slot = c.state["prof_"+ps.id+"_0"];
      return slot ? slot.trait.category : null;
    }).filter(Boolean);
    if (picks.length < 3) return;
    const counts = {};
    picks.forEach(p=> counts[p] = (counts[p]||0)+1);
    const [topCat, topCount] = Object.entries(counts).sort((a,b)=>b[1]-a[1])[0];
    const ratio = topCount / picks.length;
    if (ratio >= 0.67) profClustered.push({section: ps.label, cat: topCat, ratio, count: topCount, total: picks.length});
  });
  profClustered.sort((a,b)=>b.ratio-a.ratio);

  let h = "";
  const verdict = clustered.length >= 5
    ? "Heavily clustered — this cast risks sounding like one person in several coats."
    : clustered.length >= 3
      ? "Somewhat clustered — a few axes where everyone agrees. Worth breaking one or two."
      : "Well spread — the cast covers meaningfully different ground.";
  h += `<div class="charMeta">${verdict}</div>`;

  if (profClustered.length){
    h += `<div class="axisGroup"><div class="axisTitle">Everyone plays the same part</div>`;
    // Humor Style and Habits & Vices are inside this same generic PROFILE_SECTIONS
    // walk, but "everyone's funny the same way" (or has the same vice) is a common
    // enough ensemble failure mode that it's worth a callout more specific than the
    // generic "same narrative role" line, which was written with Role/Values in mind.
    const SECTION_CALLOUTS = {
      "Humor Style": "Same personality contrast doesn't help if everyone's funny the same way — flat humour range reads as flat cast, even with sharp axis contrast elsewhere.",
      "Habits & Vices": "A cast that's all the same standing vice (or all clean) tends to blur together outside the main conflict — vices are cheap, high-signal texture to differentiate.",
    };
    profClustered.forEach(c=>{
      const callout = SECTION_CALLOUTS[c.section] || "Same personality contrast doesn't help if everyone's playing the same narrative role.";
      h += `<div class="traitCard"><div class="traitMain">
        <div class="traitName">${c.section}</div>
        <div class="traitDesc">${c.count} of ${c.total} cast members resolved to <b>${c.cat}</b>. ${callout}</div>
      </div></div>`;
    });
    h += `</div>`;
  }
  if (clustered.length){
    h += `<div class="axisGroup"><div class="axisTitle">Everyone lands the same way here</div>`;
    clustered.forEach(c=>{
      h += `<div class="traitCard"><div class="traitMain">
        <div class="traitName">${c.axis.label}</div>
        <div class="traitDesc">All (or nearly all) of the cast sit on the <b>${c.dir}</b> side. Consider flipping one character to create contrast.</div>
      </div></div>`;
    });
    h += `</div>`;
  }
  if (spread.length){
    h += `<div class="axisGroup"><div class="axisTitle">Healthy contrast already</div>`;
    spread.forEach(s=>{
      h += `<div class="traitCard"><div class="traitMain"><div class="traitName">${s.axis.label}</div>
        <div class="traitDesc">The cast is genuinely split on this axis.</div></div></div>`;
    });
    h += `</div>`;
  }

  const box = document.getElementById('balanceResult');
  box.classList.add('show');
  box.innerHTML = h;
}


// ================= PROFILE SECTION UI =================
function buildProfileSectionUI(){
  const grid = document.getElementById('profileSectionsGrid');
  grid.innerHTML = "";
  PROFILE_SECTIONS.forEach(ps=>{
    const cats = catsOf(ps.section);
    const div = document.createElement('div');
    div.className = "profCard";
    const typeControl = ps.drawAll
      ? `<div class="blurb">Draws one from each: ${cats.join(", ")}.</div>`
      : `<select id="type_${ps.id}">
           <option value="">Auto (from personality)</option>
           ${cats.map(c=>`<option value="${c}">${c}</option>`).join("")}
         </select>`;
    div.innerHTML = `
      <div class="head">
        <input type="checkbox" id="sec_${ps.id}" checked>
        <label for="sec_${ps.id}">${ps.label}</label>
      </div>
      <div class="blurb">${ps.blurb}</div>
      ${typeControl}
    `;
    grid.appendChild(div);
  });
}
function setAllProfileSections(on){
  PROFILE_SECTIONS.forEach(ps=>{ const el=document.getElementById('sec_'+ps.id); if(el) el.checked = on; });
}
function randomizeProfileTypes(){
  PROFILE_SECTIONS.forEach(ps=>{
    const sel = document.getElementById('type_'+ps.id);
    if (!sel) return;
    const opts = [...sel.options].filter(o=>o.value);
    sel.value = Math.random() < 0.25 ? "" : opts[Math.floor(Math.random()*opts.length)].value;
  });
}

// ---------- Session preference persistence -------------------------------
// Remembers the knobs (not the character) so returning users don't have to
// re-set counts, rarity and mode on every visit. Deliberately excludes slider
// positions and the generated sheet: those are per-character choices, and
// silently restoring them would make "fresh start" behave unpredictably.
const PREF_KEY = 'prefs:v1';
const PREF_FIELDS = ['mannerCount','vocabCount','personalityCount','profileDepth',
                     'rarityPref','affinityBoost','rangeFocus','profileWeight',
                     'app_stature','app_upkeep','app_presence'];
const PREF_TOGGLES = ['personalityToggle','depthFirstToggle','examplesToggle',
                      'genPersonality','genSpeech','genVocab','genManner','genAppearance'];
let prefsReady = false;

async function savePrefs(){
  if (!prefsReady) return; // don't persist the defaults we just wrote during load
  try {
    const data = {fields:{}, toggles:{}};
    PREF_FIELDS.forEach(id=>{ const el=document.getElementById(id); if(el) data.fields[id]=el.value; });
    PREF_TOGGLES.forEach(id=>{ const el=document.getElementById(id); if(el) data.toggles[id]=el.checked; });
    await storage.set(PREF_KEY, JSON.stringify(data));
  } catch(e){ /* storage unavailable — preferences just won't persist */ }
}

async function loadPrefs(){
  try {
    const res = await storage.get(PREF_KEY);
    if (res && res.value){
      const data = JSON.parse(res.value);
      Object.entries(data.fields||{}).forEach(([id,v])=>{
        const el = document.getElementById(id);
        // only accept values the control actually offers, in case options changed
        if (!el) return;
        if (el.tagName === 'SELECT'){
          if ([...el.options].some(o=>o.value===v)) el.value = v;
        } else { el.value = v; }
      });
      Object.entries(data.toggles||{}).forEach(([id,v])=>{
        const el = document.getElementById(id); if (el) el.checked = !!v;
      });
    }
  } catch(e){ /* no saved prefs, or storage unavailable */ }
  prefsReady = true;
  try { onSliderChange(); } catch(e){}
  const ex = document.getElementById('examplesToggle');
  if (ex) { try { toggleExamples(); } catch(e){} }
}

function wirePrefPersistence(){
  PREF_FIELDS.concat(PREF_TOGGLES).forEach(id=>{
    const el = document.getElementById(id);
    if (el) el.addEventListener('change', savePrefs);
  });
}

